window.LION_KB={"meta": {"name": "Lions Guide (unofficial)", "built": "2026-11-19", "note": "Curated seed knowledge base. Paraphrased from lionsclubs.org pages and Lions-affiliated sites; each entry links to its source. Run the crawler to add the full resource center.", "version": "0.11.5", "checked": "2026-11-18", "build": "2026-11-19 07:35 UTC", "logo": "logo.png"}, "sources": {"mission-history": {"url": "https://www.lionsclubs.org/en/discover-our-clubs/interactive-timeline", "label": "Lions Clubs International: Our History", "tier": "official"}, "about-node": {"url": "https://www.lionsclubs.org/en/about-us/our-organization/about-lions-international", "label": "Lions Clubs International: About", "tier": "official"}, "new-members": {"url": "https://www.lionsclubs.org/en/resources-for-members/new-members", "label": "New Member Welcome", "tier": "official"}, "mrc": {"url": "https://lionsclubs.org/en/member-resource-center", "label": "Member Resource Center", "tier": "official"}, "service-programs": {"url": "https://lionsclubs.org/en/service-programs", "label": "Service Programs", "tier": "official"}, "club-types": {"url": "https://lionsclubs.org/node/14991", "label": "Club and membership types", "tier": "official"}, "join": {"url": "https://lionsclubs.org/join", "label": "Join Lions", "tier": "official"}, "ethics": {"url": "https://www.lionsclubs.org/sites/default/files/Board-Policy-Manual/Chapter_6_en.pdf", "label": "Board Policy Manual, Chapter VI: Code of Ethics", "tier": "official"}, "gst": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/gst-toolbox", "label": "Global Service Team Toolbox", "tier": "official"}, "campus": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/campus-lions-club", "label": "Campus Lions Club", "tier": "official"}, "leo-faqs": {"url": "https://lionsclubs.org/en/resources-for-members/resource-center/leo-faqs", "label": "Leo Club FAQs", "tier": "official"}, "leo-lion": {"url": "https://lionsclubs.org/en/resources-for-members/resource-center/leo-lion-program", "label": "Leo-Lion Program", "tier": "official"}, "lcif-blog": {"url": "https://lionsclubs.org/en/blog/A-World-in-Need,-a-Foundation-of-Support", "label": "A World in Need, a Foundation of Support (LCIF)", "tier": "official"}, "gma": {"url": "https://lionsclubs.org/en/global", "label": "Global Membership Approach", "tier": "official"}, "young-lions": {"url": "https://lionsclubs.org/hi/node/16981", "label": "Young Lions hub", "tier": "official"}, "options": {"url": "https://www.lionsclubs.org/node/18641", "label": "Membership options", "tier": "official"}, "leaders-page": {"url": "https://www.lionsclubs.org/en/discover-our-clubs/our-leaders", "label": "Lions Clubs International: Our Leaders", "tier": "official"}, "lcif-toolkit": {"url": "https://www.lionsclubs.org/en/member-resource-center/leaders/resources/lcif-leadership-toolkit", "label": "LCIF Leadership Toolkit", "tier": "official"}, "brand-page": {"url": "https://www.lionsclubs.org/en/resources-for-members/brand-guidelines", "label": "Brand Guidelines, Logos and Brand", "tier": "official"}, "pg-pay": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/payment-instructions", "label": "Payment Instructions", "tier": "official"}, "pg-fin": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/finance-resources", "label": "Finance Resources", "tier": "official"}, "pg-svc": {"url": "https://www.lionsclubs.org/en/member-resource-center/service/resources/service-journey/service-reporting", "label": "Service Reporting", "tier": "official"}, "pg-ins": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/insurance", "label": "Insurance", "tier": "official"}, "pg-cert": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/certificate-of-insurance", "label": "Certificate of Insurance", "tier": "official"}, "pg-mg": {"url": "https://www.lionsclubs.org/en/member-resource-center/grants-and-awards/foundation-grants/lcif-grants-toolkit/matching-grant", "label": "Matching Grant Program", "tier": "official"}, "pg-leo": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/start-a-leo-club", "label": "Starting a Leo Club", "tier": "official"}, "pg-stu": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/student-member-program", "label": "Student Member Program", "tier": "official"}, "pg-new": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/start-a-new-club", "label": "Start a New Club", "tier": "official"}, "pg-rec": {"url": "https://www.lionsclubs.org/en/member-resource-center/membership/increase-membership/member-recruitment", "label": "Member Recruitment", "tier": "official"}, "pg-dg": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/district-governors", "label": "Managing Your District (district governors)", "tier": "official"}, "pg-club": {"url": "https://www.lionsclubs.org/en/member-resource-center/leaders/club/managing-your-club", "label": "Managing Your Club", "tier": "official"}, "pg-mem": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/club-membership-chairperson", "label": "Club Membership Chairperson", "tier": "official"}, "pg-mkt": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/club-marketing-communications-chairperson", "label": "Club Marketing", "tier": "official"}, "pg-md": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/managing-your-multiple-district", "label": "Managing Your Multiple District", "tier": "official"}, "pg-helen": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/helen-keller", "label": "Helen Keller", "tier": "official"}, "rc-library": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center", "label": "Resource Center", "tier": "official"}, "pg-fam": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/family-membership", "label": "Family Membership", "tier": "official"}, "pg-legal": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/legal-resources", "label": "Legal Resources", "tier": "official"}, "pg-zone": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/zone-region-chairpersons", "label": "Managing Your Zone and Region", "tier": "official"}, "pg-gat": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/global-action-team", "label": "Global Action Team (GAT)", "tier": "official"}, "pg-gatr": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/global-action-team-roles-resources", "label": "Global Action Team (GAT) Roles and Resources", "tier": "official"}, "pg-gmt": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/gmt-and-get-toolkit", "label": "Global Membership Team and Global Extension Team Toolbox", "tier": "official"}, "pg-glt": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/glt-toolbox", "label": "Global Leadership Team Toolbox", "tier": "official"}, "pg-gst": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/gst-toolbox", "label": "Global Service Team Toolbox", "tier": "official"}, "la2": {"url": "https://www.lionsclubs.org/en/resources-for-members/resource-center/legal-resources", "label": "Standard Club Constitution and By-Laws (LA-2, FY 2026-27, revised October 6, 2026)", "tier": "official"}}, "tour": ["what-is-lions", "mission-vision", "history", "global-causes", "lcif", "club-types", "how-to-join", "new-member-first-steps"], "entries": [{"id": "what-is-lions", "cat": "Basics", "level": "new", "title": "What is Lions Clubs International?", "questions": ["what is lions club", "what is lionism", "who are the lions", "tell me about lions clubs international", "what do lions do", "is lions a service club", "how many members does lions have", "how many clubs are there", "how many countries are lions in", "how big is lions clubs international", "are lions a religious group"], "answer": "Lions Clubs International is the world's largest service club organisation. Ordinary people join local clubs, called Lions clubs, and volunteer their time and money to help their communities and people in need. A member is called a Lion. The motto is \"We Serve\".", "facts": ["About 1.4 million members in roughly 49,000 to 50,000 clubs", "Active in over 200 countries and geographic areas", "Over 100 years of service, founded 1917", "Lions serve hundreds of millions of people every year", "Lions and Leos serve through eight global causes and other local projects"], "tags": ["lions", "lionism", "overview", "service club", "volunteer", "organization", "organisation", "about"], "related": ["mission-vision", "history", "global-causes", "how-to-join"], "src": ["new-members", "mission-history"]}, {"id": "mission-vision", "cat": "Basics", "level": "new", "title": "Mission and vision", "questions": ["what is the mission of lions", "lions vision statement", "why do lions exist", "what is lions mission statement"], "answer": "The mission of Lions Clubs International is to empower Lions clubs, volunteers and partners to improve health and wellbeing, strengthen communities, and support those in need through humanitarian service and grants that impact lives globally, and encourage peace and international understanding.", "facts": ["Mission wording is from Lions Clubs International's own About page"], "tags": ["mission", "vision", "purpose", "goal", "why"], "related": ["core-values"], "src": ["about-node"]}, {"id": "code-of-ethics", "cat": "Values", "level": "new", "title": "The Lions Code of Ethics", "questions": ["lions code of ethics", "what are the ethics of lions", "lion rules of conduct", "lions values for members", "how should a lion behave"], "answer": "The Code of Ethics is a personal guide for how each Lion should act. In plain words: work with quality and industry, seek success but never at the cost of self-respect, do not build yourself up by tearing others down, settle doubts about right and wrong against yourself, treat friendship as an end and not a means, be a good citizen, help those in distress, and be careful with criticism and generous with praise.", "facts": ["The Code of Ethics is in Chapter VI of the Board Policy Manual on lionsclubs.org"], "tags": ["ethics", "code", "conduct", "behaviour", "behavior", "integrity", "rules"], "related": ["core-values"], "src": ["ethics"]}, {"id": "core-values", "cat": "Values", "level": "new", "title": "Lions core values", "questions": ["lions core values", "what values do lions have", "lions ethical standards", "integrity accountability lions"], "answer": "Lions' ethical standards rest on core values: commitment to service, dedication to excellence, appreciation for diversity, dynamic collaboration, personal and professional integrity, and a spirit of innovation. The association says it has no tolerance for ethical violations.", "facts": ["Also stressed: safeguarding association assets, honouring commitments, and teamwork", "Source is the Board Policy Manual, Chapter VI"], "tags": ["values", "service", "excellence", "diversity", "integrity", "innovation", "accountability", "teamwork"], "related": ["code-of-ethics", "mission-vision"], "src": ["ethics"]}, {"id": "global-causes", "cat": "Service", "level": "new", "title": "Global causes: what Lions work on", "questions": ["what are the global causes", "what causes do lions support", "areas of service lions", "how many global causes", "five global causes", "eight global causes", "how many causes do lions have", "what are lions eight causes", "our global causes"], "answer": "Lions' website lists eight global causes: childhood cancer, diabetes, disaster relief, the environment, humanitarian aid, hunger, vision and youth. Earlier Lions material spoke of five global causes (diabetes, vision, hunger, the environment and childhood cancer), with disaster relief, youth programs and wider humanitarian work as further service areas. Every club can pick the causes that fit its community, and also serve local needs outside them.", "facts": ["The eight causes: Childhood cancer, Diabetes, Disaster relief, Environment, Humanitarian, Hunger, Vision, Youth", "The five long-standing focus areas are Diabetes, Vision, Hunger, Environment and Childhood Cancer", "Each cause has beginner, intermediate and advanced project ideas for clubs", "Clubs can also serve local needs outside these causes"], "tags": ["causes", "global causes", "service", "projects", "focus areas", "what lions do"], "related": ["cause-diabetes", "cause-vision", "cause-hunger", "cause-environment", "cause-childhood-cancer", "disaster-relief"], "src": ["service-programs", "join", "lcif-blog"]}, {"id": "cause-diabetes", "cat": "Service", "level": "new", "title": "Diabetes", "questions": ["lions diabetes", "diabetes screening lions", "diabetes camps", "strides for diabetes", "what do lions do about diabetes", "diabetes support group"], "answer": "Lions work to reduce how common diabetes is and to improve life for people living with it. Clubs run Type 2 diabetes screening events, \"Strides\" walks and runs that raise awareness, diabetes camps for young people, and peer support groups.", "facts": ["Type 2 Diabetes Screening: clubs use step-by-step guides", "Strides for Diabetes Awareness: any physical activity, such as a run or dance event", "Diabetes Camps: help young people build diabetes management skills", "Diabetes Support Groups: peer groups sponsored by a club or district"], "tags": ["diabetes", "sugar", "screening", "camp", "health", "strides"], "related": ["global-causes", "lcif"], "src": ["service-programs"]}, {"id": "cause-vision", "cat": "Service", "level": "new", "title": "Vision and eye care", "questions": ["lions vision", "eye care lions", "vision screening", "eye bank", "lions kidsight", "recycle eyeglasses", "donate glasses", "sightfirst", "blindness prevention"], "answer": "Vision is Lions' oldest cause. Clubs screen children and adults for vision problems, run the KidSight program for children from 6 months old, sponsor eye banks that supply eye tissue for sight restoration, and collect used eyeglasses for people who cannot afford them.", "facts": ["Vision Screening: with medical professionals and community leaders", "Lions KidSight: screening and referral from age 6 months", "Lions Eye Banks: recover, test, store and distribute eye tissue", "Eyeglass Recycling: used glasses go to the Lions Recycle For Sight program"], "tags": ["vision", "eye", "eyes", "sight", "blind", "blindness", "glasses", "eyeglasses", "cataract", "screening", "kidsight", "eye bank"], "related": ["helen-keller", "global-causes", "lcif"], "src": ["service-programs", "lcif-blog"]}, {"id": "cause-hunger", "cat": "Service", "level": "new", "title": "Hunger", "questions": ["lions hunger", "food bank lions", "what do lions do about hunger", "lions food security", "feed the hungry"], "answer": "Through the hunger cause, Lions work to make sure everyone in a community has access to nutritious food. Clubs support food banks and food distribution, and LCIF grants can fund food bank and distribution infrastructure, transport, and commercial refrigeration and freezers.", "facts": ["Goal: improve food security and access to nutritious food", "Grants can pay for food bank equipment and transport"], "tags": ["hunger", "food", "nutrition", "food bank", "malnutrition"], "related": ["global-causes", "lcif-grants"], "src": ["join", "lcif-blog"]}, {"id": "cause-environment", "cat": "Service", "level": "new", "title": "Environment", "questions": ["lions environment", "lions clean water", "environment projects", "tree planting lions", "lions sanitation"], "answer": "The environment cause is about protecting and restoring the natural world to improve people's wellbeing. LCIF funding in this area has paid for water tanks, wells and pumps, water purification for schools and clinics, and toilets and sanitation where none exist.", "facts": ["Goal: sustainably protect and restore the environment", "LCIF Campaign 100 material noted that at least 1.8 billion people use drinking water contaminated by faecal matter"], "tags": ["environment", "water", "sanitation", "green", "climate", "trees", "clean"], "related": ["global-causes", "lcif-grants"], "src": ["join", "lcif-blog"]}, {"id": "cause-childhood-cancer", "cat": "Service", "level": "new", "title": "Childhood cancer", "questions": ["lions childhood cancer", "children with cancer", "what do lions do for kids with cancer", "pediatric oncology"], "answer": "Lions support children and families affected by childhood cancer. Funding has gone to pediatric oncology services in developing countries, medical and lab equipment, vehicles for patient travel, and family lodging and camp facilities. Lions also work with the partner Global HOPE to improve standards of care.", "facts": ["A Childhood Cancer Grant program exists, with its own criteria and application form", "Campaign 100 material: a child is diagnosed about every two minutes; survival is around 80% in high-income countries but may be only 10 to 20% in low- and middle-income countries"], "tags": ["childhood cancer", "cancer", "children", "kids", "hospital", "oncology", "family"], "related": ["global-causes", "lcif-grants"], "src": ["join", "lcif-blog"]}, {"id": "disaster-relief", "cat": "Service", "level": "new", "title": "Disaster relief", "questions": ["lions disaster relief", "flood relief", "earthquake help lions", "disaster relief fund", "emergency grants"], "answer": "Lions respond when disasters hit, providing immediate needs like food, water, clothing and medical supplies, and later helping rebuild homes and facilities. People can donate to the Disaster Relief Fund, which is reserved only for disaster relief.", "facts": ["LCIF has invested about US$130 million in disaster-related grants since 1970 (Campaign 100 material)", "Donations to LCIF go to either the Empowering Service Fund or the Disaster Relief Fund"], "tags": ["disaster", "relief", "flood", "earthquake", "emergency", "hurricane", "fund"], "related": ["lcif", "lcif-grants"], "src": ["lcif-blog", "mrc"]}, {"id": "youth", "cat": "Service", "level": "new", "title": "Youth programs", "questions": ["lions youth programs", "lions for kids", "peace poster contest", "youth camps and exchange", "lions quest", "how do lions help young people"], "answer": "Lions run several programs for young people: Leo clubs for ages 12 to 30, the Youth Camps and Exchange program that promotes understanding and peace, the annual Peace Poster and Peace Essay contests, and Lions Quest, a school-based program for young people.", "facts": ["Youth Camps and Exchange excludes tourism, academic study and employment", "Lions Quest has reached 17+ million students in over 100 countries (Campaign 100 material)", "Peace Poster and Essay entries move from club to district to multiple district, then to Lions headquarters"], "tags": ["youth", "kids", "children", "students", "peace poster", "essay", "camp", "exchange", "lions quest", "school"], "related": ["leo-clubs", "young-lions"], "src": ["service-programs", "lcif-blog", "mrc"]}, {"id": "service-programs", "cat": "Service", "level": "member", "title": "Service programs clubs can run", "questions": ["lions service programs", "service project ideas", "what projects can my club do", "project planners", "lions programs list"], "answer": "Lions International offers ready-made service programs so clubs do not start from scratch: Type 2 Diabetes Screening, Strides for Diabetes Awareness, Diabetes Camps and Support Groups, Vision Screening, Lions KidSight, Lions Eye Banks, Eyeglass Recycling, and Youth Camps and Exchange. Downloadable Service Project Planners and beginner-to-advanced ideas exist for each cause.", "facts": ["Projects are grouped by global cause", "The Global Service Team site gathers the planners, ideas and grants"], "tags": ["programs", "projects", "planner", "ideas", "club projects"], "related": ["gst", "global-causes"], "src": ["service-programs", "gst"]}, {"id": "lcif", "cat": "Foundation", "level": "new", "title": "LCIF: the Lions foundation", "questions": ["what is lcif", "lions clubs international foundation", "what is the lions foundation", "lcif history", "who funds lcif", "how is lcif funded"], "answer": "LCIF, the Lions Clubs International Foundation, is the charitable arm of Lions. Founded in 1968, it gives grants that power Lions' service, and has awarded over US$1.3 billion so far. Its work centres on three goals: health and well-being, stronger communities, and support for people in need.", "facts": ["Founded 1968", "Funded by Lions, corporate, government and foundation partners, and other supporters", "Grants support Lions' local and global projects", "Donations on lionsclubs.org support LCIF"], "tags": ["lcif", "foundation", "grants", "charity", "donate", "funding"], "related": ["lcif-grants", "disaster-relief", "global-causes"], "src": ["new-members", "lcif-blog"]}, {"id": "lcif-grants", "cat": "Foundation", "level": "member", "title": "What LCIF grants and donations pay for", "questions": ["how do i get an lcif grant", "what do lcif grants fund", "where does my donation go", "lions grants", "campaign 100", "how to donate to lions"], "answer": "LCIF grants have paid for expanded eye care, education programs, disaster recovery, diabetes screening and camps, pediatric cancer equipment and family lodging, food bank infrastructure, and clean water and sanitation. Donations go to one of two funds: the Empowering Service Fund for all causes, or the Disaster Relief Fund for disasters only.", "facts": ["Campaign 100 was LCIF's centennial fundraising campaign", "Each grant type has its own criteria and application form; check the Member Resource Center for the current ones"], "tags": ["grants", "donate", "donation", "campaign 100", "funding", "empowering service fund"], "related": ["lcif", "disaster-relief"], "src": ["lcif-blog", "gst"]}, {"id": "how-to-join", "cat": "Joining", "level": "new", "title": "How to join Lions", "questions": ["how do i join lions", "how to become a lion", "join lions club", "how can i become a member", "find a lions club near me", "club locator", "can i join", "is there a lions club in my city", "is there a lions club in my town", "is there a club near me"], "answer": "Use the Find a Club tool on the Lions website to see clubs near you, then contact one and attend a meeting or a service project. If no club suits you, you can start a new one. You can choose a club type that fits your life: traditional, specialty (shared interest), virtual (online), campus (students), club branch (a smaller group within an existing club) or Leo (ages 12 to 30).", "facts": ["Find a club: lionsclubs.org/en/join", "Membership questions: membership@lionsclubs.org", "Membership types include regular, family, student and Leo", "Ask \"what are the types of Lions clubs\" for details of each type"], "tags": ["join", "become", "membership", "member", "find a club", "locator", "near me", "sign up", "apply"], "related": ["club-types", "membership-types", "new-member-first-steps"], "src": ["join", "options", "club-types"]}, {"id": "club-types", "cat": "Joining", "level": "new", "title": "Types of Lions clubs", "questions": ["types of lions clubs", "what kinds of clubs are there", "traditional club", "specialty club", "virtual club", "which club should i join", "club options", "can i attend meetings online", "what is the difference between traditional and specialty clubs", "clubs that meet by video call", "can lions meet on zoom", "what are the different types of lions clubs", "what is a campus lions club", "what is a specialty club", "what is a virtual lions club"], "answer": "Lions clubs come in several types, so you can choose what fits your life. Traditional clubs meet locally and regularly. Specialty clubs unite members around a shared interest, hobby, cause or profession, with the same chartering process as other clubs. Virtual clubs plan and meet online or by phone and still coordinate in-person service. Campus Lions clubs are for students, on or off campus, and need at least five student charter members among the 20 minimum. Club branches are groups of at least five people who belong to an existing parent club but hold their own meetings and activities, led through a branch liaison. Leo clubs are for young people aged 12 to 30.", "facts": ["Traditional: service-minded people who meet locally and regularly", "Specialty: members share an interest, hobby, cause or profession", "Virtual: some or all meetings held remotely, good for busy or spread-out members", "Campus: students, on or off campus; at least 5 student charter members within the 20 minimum", "Club branch: at least 5 members, a parent club and a branch liaison; district governor notified", "Leo: Alpha 12 to 18, Omega 18 to 30"], "tags": ["club types", "traditional", "specialty", "virtual", "campus", "leo", "options", "online"], "related": ["campus-club", "leo-clubs", "club-branch", "membership-types"], "src": ["club-types", "options"]}, {"id": "membership-types", "cat": "Joining", "level": "new", "title": "Membership types and discounts", "questions": ["membership types", "family membership", "student membership", "lions dues discount", "can my family join together"], "answer": "Four main kinds of membership: regular, family, student, and Leo. Family membership is for relatives in the same household and has a reduced dues rate. Student membership is for students from the legal age of majority up to under 30 and gives a discount on international dues. Leo members, aged 12 to 30, pay no membership fee. Local club dues vary and are set by each club.", "facts": ["Children cannot be members but can take part in the Cub program", "Leo-Lion members get a 50% discount on international dues"], "tags": ["membership", "dues", "fees", "cost", "family", "student", "discount", "price", "how much"], "related": ["leo-lion", "campus-club", "how-to-join"], "src": ["club-types", "leo-lion", "campus"]}, {"id": "campus-club", "cat": "Joining", "level": "new", "title": "Campus Lions clubs", "questions": ["campus lions club", "lions club for students", "how to start a campus lions club", "student member program", "charter members for campus club"], "answer": "A Campus Lions club is open to any student, living on or off campus, full-time or part-time. To charter one you need at least 20 charter members, of whom at least five are students. The usual route is to get approved as a registered student club with your school's student activities office.", "facts": ["Benefits: service hours, resume-building training, networking, and Student Member Program discounts", "If the school does not approve, you can charter an independent Campus Lions club, but may lose the school's name, campus venues and funding", "Student Member Program covers students from legal age of majority to under 30"], "tags": ["campus", "student", "college", "university", "charter", "school"], "related": ["club-branch", "young-lions", "leo-lion"], "src": ["campus", "young-lions"]}, {"id": "club-branch", "cat": "Joining", "level": "member", "title": "Club branches", "questions": ["what is a club branch", "start a lions group with five people", "small lions group", "club branch requirements"], "answer": "A club branch is a small group that can meet and serve on its own while getting support from a parent Lions club. It needs only five members, so it suits people who want to form a group but do not have the 20 charter members a full club needs. Alumni of a Campus Lions club can also use a branch to stay connected.", "facts": ["Minimum members: five", "A full new Lions club needs 20 charter members"], "tags": ["club branch", "branch", "five members", "small group", "charter"], "related": ["campus-club", "club-types"], "src": ["campus"]}, {"id": "leo-clubs", "cat": "Youth", "level": "new", "title": "Leo clubs", "questions": ["what are leo clubs", "leo club age", "alpha leo omega leo", "how to start a leo club", "leo club fees", "leo club advisor", "sponsor a leo club", "how old do you have to be to join a leo club", "what is the age limit for leo", "what age can kids join leos", "programme for teenagers", "my teenager wants to volunteer"], "answer": "Leo clubs are youth programs sponsored by Lions clubs for people aged 12 to 30. Alpha Leo clubs are for ages 12 to 18, and Omega Leo clubs are for ages 18 to 30. A sponsoring Lions club names an advisor, ideally someone who enjoys working with young people.", "facts": ["One-time organisation fee: US$100 (certificate, officer kit, sponsor kit, lapel pins)", "Annual levy: US$100 per Leo club, billed to the sponsoring Lions club each July and waived in the year the club is certified", "To charter: organise the club and elect officers, then the sponsoring Lions club president submits the Leo Club Organization Report (Leo-51)", "Certification may take 4 to 6 weeks", "Two or more Lions clubs can jointly sponsor one Leo club"], "tags": ["leo", "leos", "alpha", "omega", "youth", "teen", "advisor", "sponsor", "levy", "leo-51"], "related": ["leo-lion", "youth", "club-types"], "src": ["leo-faqs", "club-types"]}, {"id": "leo-lion", "cat": "Youth", "level": "new", "title": "Leo-Lion program (Leos becoming Lions)", "questions": ["leo to lion", "leo lion program", "what happens when a leo ages out", "leo lion benefits", "leo-lion membership"], "answer": "The Leo-Lion program helps Leos move up into Lions. Current or former Leos who served at least a year and a day, from the legal age of majority through age 35, can join as Leo-Lions. They get a 50% discount on international dues, a waived entrance or charter fee, credit for their Leo years, and access to special scholarships and online learning.", "facts": ["Leo records are automatically closed on June 30 of the Lion year if the Leo has reached the maximum age", "Short-term dual Leo and Lion membership is allowed", "Leo-Lions can serve in any club type, and as liaisons to boards and councils"], "tags": ["leo lion", "leo-lion", "transition", "age out", "graduate", "young lions"], "related": ["leo-clubs", "young-lions", "membership-types"], "src": ["leo-lion"]}, {"id": "young-lions", "cat": "Youth", "level": "new", "title": "Young Lions", "questions": ["young lions", "lions for young adults", "under 30 lions", "young professionals lions", "student member"], "answer": "Young Lions are members aged roughly 40 or younger. If you are 30 or under and in school, the Student Member Program gives discounted dues and extra fee waivers. Campus clubs, specialty clubs, club branches and the Leo-Lion program are all aimed at helping younger people serve in a way that suits them.", "facts": ["Questions: membership@lionsclubs.org", "Young Lions have their own hub on the Lions website"], "tags": ["young lions", "young adults", "youth", "students", "under 30", "under 40"], "related": ["campus-club", "leo-lion", "club-types"], "src": ["young-lions", "gma"]}, {"id": "new-member-first-steps", "cat": "Joining", "level": "new", "title": "Your first steps as a new Lion", "questions": ["new member orientation", "i just joined lions what now", "first steps for new lion", "what should a new lion do first", "how do i begin as a new member"], "answer": "Start by going to your club meetings and joining its service projects. Register on the Lion Portal, complete the New Member Orientation course, and explore the Member Resource Center, which holds Lions news, resources and tools. Following Lions on social media is also encouraged.", "facts": ["Lion Portal: where members register and manage their Lions account", "Lions Learning Center: online courses, including New Member Orientation", "Member Resource Center: news, resources and information"], "tags": ["new member", "orientation", "getting started", "first steps", "lion portal", "learning center", "welcome", "onboarding"], "related": ["glossary-lion-portal", "how-to-join", "gst"], "src": ["new-members", "mrc"]}, {"id": "gst", "cat": "For members", "level": "member", "title": "Global Service Team (GST) toolbox", "questions": ["what is the global service team", "gst toolbox", "service reporting", "kindness matters award", "service journey learn discover act celebrate", "how do clubs report service"], "answer": "The Global Service Team helps clubs find resources and best practices to make their projects better. The toolbox covers service programs and planners, advocacy, service reporting, service awards and LCIF grants. Its service journey has four phases: Learn, Discover, Act and Celebrate.", "facts": ["Kindness Matters Service Award: clubs are nominated at club level; a few each year are recognised for outstanding projects in a global cause", "Lions-Elevance Health Volunteer Days: clubs in specified US cities can apply for grants up to US$2,500 each spring", "Related toolboxes: Global Action Team, Global Leadership Team, Global Membership Team"], "tags": ["gst", "global service team", "toolbox", "reporting", "awards", "kindness matters", "service journey", "advocacy"], "related": ["service-programs", "lcif-grants", "gma"], "src": ["gst"]}, {"id": "gma", "cat": "For members", "level": "member", "title": "Global Membership Approach", "questions": ["global membership approach", "how to grow lions membership", "revitalize a club", "start a new lions club", "get new members for my club", "rebuild a struggling club", "what does gma stand for"], "answer": "The Global Membership Approach is a step-by-step process that helps districts grow. It focuses on starting new clubs and bringing new members into existing clubs, then keeping members engaged. An eLearning course on it is available in the Lions Learning Center.", "facts": ["Related options: Campus clubs, Specialty clubs, Club branches, Young Lions", "Resources include a customizable \"We are Lions\" poster for marketing a club"], "tags": ["membership growth", "gma", "recruit", "new club", "revitalize", "rebuild", "retention"], "related": ["club-types", "mission-1-5"], "src": ["gma"]}, {"id": "mission-1-5", "cat": "For members", "level": "member", "title": "MISSION 1.5", "questions": ["mission 1.5", "1.5 million members goal", "mission 1.5 awards", "lions membership goal"], "answer": "MISSION 1.5 is Lions' goal of reaching 1.5 million members worldwide by 2027. The MISSION 1.5 Awards recognise growth in membership, and the Member Resource Center lists ways to recruit members.", "facts": ["Current membership is about 1.4 million", "Details and the latest award rules are on the Member Resource Center"], "tags": ["mission 1.5", "goal", "1.5 million", "awards", "growth", "2027"], "related": ["gma", "what-is-lions"], "src": ["mrc"]}, {"id": "structure", "cat": "structure", "level": "general", "title": "How Lions is organised", "questions": ["how is lions organised", "structure of lions clubs international", "lions hierarchy", "club district multiple district international", "levels of lions", "how is lions structured", "organisation structure of lions"], "answer": "Lions are organised in levels. A local club belongs to a district, led by a district governor. Zones and regions group clubs within a district for support. Districts can form a multiple district, supported by a council chairperson and the Council of Governors. At the top is Lions Clubs International, led by the International Board of Directors and the International President, who for 2026-27 is Mark S. Lyon. Lions Clubs International Foundation (LCIF) provides grants that support the service of members.", "facts": ["Club level: club president, vice president, secretary, treasurer and chairpersons", "District level: district governor and the district cabinet", "International level: executive officers and elected directors"], "tags": ["structure", "levels"], "related": ["titles-international", "titles-club"], "src": ["pg-dg", "pg-md", "pg-zone", "leaders-page", "about-node"]}, {"id": "advocacy", "cat": "For members", "level": "member", "title": "Advocacy for clubs", "questions": ["lions advocacy", "how can clubs advocate", "influence policy lions"], "answer": "Advocacy means a club using its voice to raise awareness, influence laws and policy, and build partnerships around the causes it serves. The Global Service Team toolbox has guidance for it.", "facts": ["Advocacy sits alongside service planning, reporting, awards and grants in the GST toolbox"], "tags": ["advocacy", "policy", "awareness", "partnerships"], "related": ["gst"], "src": ["gst"]}, {"id": "contact-lci", "cat": "Help", "level": "new", "title": "Contact Lions Clubs International", "questions": ["contact lions", "lions headquarters address", "lions phone number", "lions email", "membership email", "where is lions headquarters"], "answer": "Lions Clubs International headquarters is at 300 W. 22nd Street, Oak Brook, Illinois 60523-8842, USA. The main phone is +1 630 571 5466. For membership questions write to membership@lionsclubs.org.", "facts": ["Contact forms are on lionsclubs.org under Contact LCI and Contact LCIF"], "tags": ["contact", "address", "phone", "email", "headquarters", "oak brook", "help"], "related": ["how-to-join"], "src": ["mrc", "leo-lion"]}, {"id": "glossary-lion-portal", "cat": "Glossary", "level": "new", "title": "Lion Portal, MyLCI and Lions Learning Center", "questions": ["what is the lion portal", "what is mylci", "what is lions learning center", "what is the member resource center"], "answer": "These are the online tools for members. The Lion Portal is where you register and manage your Lions account, MyLCI is where clubs maintain membership records, the Lions Learning Center holds online courses, and the Member Resource Center collects news and resources.", "facts": ["Club secretaries typically use MyLCI to update member records"], "tags": ["lion portal", "mylci", "learning center", "member resource center", "online", "tools"], "related": ["new-member-first-steps"], "src": ["new-members", "leo-lion", "mrc"]}, {"id": "glossary-terms", "cat": "Glossary", "level": "new", "title": "Lions jargon in plain words", "questions": ["lions glossary", "what does lci mean", "what is a charter member", "what does charter mean", "lion year", "lions terms", "what is a leo"], "answer": "A Lion is a member. LCI is Lions Clubs International and LCIF is its foundation. A Leo is a youth member aged 12 to 30. Charter means officially founding a club, and charter members are the founding members. A district is a regional group of clubs. The Lions year runs July to June.", "facts": ["A new Lions club needs 20 charter members; a club branch needs five", "GST is the Global Service Team; GMA is the Global Membership Approach"], "tags": ["glossary", "terms", "jargon", "lci", "lcif", "charter", "lion", "leo", "district", "lion year", "meaning"], "related": ["structure", "lcif", "leo-clubs"], "src": ["leo-faqs", "campus", "mrc"]}, {"id": "titles-overview", "cat": "Officers and titles", "level": "member", "title": "Lions officer titles from club to International, in plain words", "questions": ["what are the lions officer titles", "lions positions and titles explained", "lions ranks", "lions structure from club to international for beginners", "what do all the lions titles mean", "who is who in lions titles and levels"], "answer": "Lions is organised like a ladder, and each rung has its own titles. Club: the president, vice presidents, secretary, treasurer and committee chairpersons run your local club. Zone: a zone chairperson looks after a small group of clubs (a region chairperson looks after several zones, where a district uses regions). District: a district governor, helped by the first and second vice district governors, leads all the clubs in an area, with a cabinet. Multiple district: where several districts are grouped, their governors form a council led by a council chairperson. International: the International President, vice presidents and directors lead the whole association, and the LCIF Chairperson leads the foundation. You only need to know the level you serve at; each rung supports the one below it.", "facts": ["Every Lions year runs July to June, and officers usually serve one year at a time", "A member only becomes a zone, region, district or international officer after serving at club level first", "Ask for any level: club, zone and region, district, multiple district, International, or LCIF area leaders"], "tags": ["titles", "officers", "hierarchy", "ranks", "structure"], "related": ["titles-club", "titles-zone-region", "titles-district", "titles-multiple-district", "titles-international", "lcif-leaders", "structure"], "src": ["mrc", "about-node"]}, {"id": "titles-district", "cat": "titles", "level": "district", "title": "District leadership roles", "questions": ["what positions are there in a lions district", "district officer titles", "who runs a lions district"], "answer": "The district governor is the chief representative of Lions International in the district. The governor leads membership growth, new club development and club retention, oversees the district Global Action Team, guides district goals, promotes leadership training and makes sure clubs follow association guidelines and stay in good standing. The governor also leads key meetings and conventions and supports LCIF. The Managing Your District page on lionsclubs.org lists the district cabinet structure, cabinet secretary and treasurer e-book, and other tools. A Lion who has served as district governor cannot be elected district governor or vice district governor again.", "facts": ["District Cabinet Structure and Cabinet Secretary / Treasurer e-Book: Managing Your District page", "Governance documents: Board Policy Manual and the Standard Constitutions"], "tags": ["district", "governor"], "related": ["structure"], "src": ["pg-dg"]}, {"id": "titles-multiple-district", "cat": "titles", "level": "multiple-district", "title": "Multiple district leadership roles", "questions": ["what is a multiple district", "council chairperson", "council of governors", "who runs a multiple district", "multiple district officers"], "answer": "A multiple district is supported by a council chairperson and a council secretary, who support the actions and decisions of the Council of Governors. Multiple districts also appoint chairpersons for areas such as Leo clubs, vision, diabetes, hunger, childhood cancer, environment, marketing, protocol, youth camps and exchange, and convention, and coordinators for the Global Leadership, Membership and Service Teams. The Managing Your Multiple District page on lionsclubs.org has the Council Chairperson e-Book, the Council Chairperson Orientation in the Lions Learning Center and the Council of Governors guide.", "facts": ["Council Chairperson e-Book and Orientation: Managing Your Multiple District page", "Multiple District Officers Report Form reports the council chairperson"], "tags": ["multiple district", "council"], "related": ["structure"], "src": ["pg-md"]}, {"id": "titles-international", "cat": "titles", "level": "international", "title": "International officers and directors", "questions": ["who is the international president", "international president of lions", "who are the international officers", "international officers and directors", "international board of directors", "lions international executive officers", "who is lions international president 2026-27", "international vice presidents"], "answer": "For 2026-27 the executive officers of Lions Clubs International are International President Mark S. Lyon (Brookfield, Connecticut, USA), Immediate Past International President A.P. Singh (Kolkata, India), First Vice President Dr. Manoj Shah (Nairobi, Kenya), Second Vice President Tony Benbow (South Vermont, Australia) and Third Vice President C. Robert Rettby (Neuchatel, Switzerland). The International Board of Directors also includes second-year and first-year international directors, and the board has appointees, Leo-Lion Board Liaisons and standing committees such as Constitution and By-Laws, Membership Development, Marketing and Service Activities.", "facts": ["Source: Our Leaders (2026-2027) page on lionsclubs.org", "Leaders change each Lions year: check the page for the current list"], "tags": ["international", "president", "board"], "related": ["structure"], "src": ["leaders-page"]}, {"id": "lcif-leaders", "cat": "Officers and titles", "level": "member", "title": "LCIF area leaders and coordinators", "questions": ["what are lcif area leaders", "what is an lcif coordinator", "what is a district lcif coordinator", "what does the lcif multiple district coordinator do", "who leads lcif"], "answer": "The Lions Clubs International Foundation has its own ladder of volunteers. LCIF area leaders are appointed by the LCIF Chairperson, usually for a three-year term, to represent the foundation across a large area. Below them each multiple district has an LCIF coordinator who acts as an ambassador for LCIF, then district coordinators, and finally the club LCIF coordinator in each club, who promotes giving and grants to members.", "facts": ["LCIF area leaders are appointed by the LCIF Chairperson, usually for three years", "The LCIF Chairperson is a separate role from the International President", "See the LCIF Leadership Toolkit for each role's responsibilities"], "tags": ["lcif", "area leader", "coordinator", "foundation"], "related": ["titles-international", "titles-district", "titles-club"], "src": ["lcif-toolkit"]}, {"id": "logo-brand", "cat": "Marketing", "level": "member", "title": "Using the Lions logo and brand", "questions": ["how do i use the lions logo", "can i use the lions logo", "where can i get the lions logo", "lions logo for my club", "lions brand guidelines", "lions emblem download", "logo permission for a website"], "answer": "Lions International keeps the logo, emblem and brand rules on its Brand Guidelines, Logos and Brand page, so every club's materials look consistent. Brand-approved versions of the Lions emblem, icons and logos for clubs are on the Logos and Emblems page, and the Lions International Brand Guidelines document explains how to use them. Social media kits and Canva templates you can customise for your club are also provided. Use the approved files rather than copying a logo from a website.", "facts": ["Brand guidelines: the Lions International Brand Guidelines document is in the library", "Ready-made social media graphics and Canva templates are on the Social Media Kits page", "If you are unsure whether a use is allowed, ask Lions International before you publish"], "tags": ["logo", "emblem", "brand", "guidelines"], "related": ["titles-club"], "src": ["brand-page"]}, {"id": "cause-humanitarian", "cat": "Service", "level": "both", "title": "Humanitarian: meeting the world's most crucial needs", "questions": ["lions humanitarian", "humanitarian aid lions", "what is the humanitarian cause", "lions humanitarian efforts"], "answer": "Humanitarian is one of Lions' eight global causes. Lions identify the world's most crucial needs and provide humanitarian aid where it is needed most, through local clubs and through grants from the Lions Clubs International Foundation.", "facts": ["Listed as a global cause on the Lions website", "Disaster relief is a separate cause for natural disasters", "Clubs can find project ideas under Service Programs on lionsclubs.org"], "tags": ["humanitarian", "aid", "relief"], "related": ["global-causes", "disaster-relief", "lcif"], "src": ["service-programs"]}, {"id": "join-cost", "cat": "membership", "level": "general", "title": "What Lions membership costs", "questions": ["how much does it cost to join lions", "what is the cost of joining a lions club", "membership fees for lions", "lions dues and fees", "how much are lions dues", "entrance fee for lions club", "is it expensive to join lions", "what are the charges to be a lion", "cost of lions membership", "lions club membership fee"], "answer": "Joining a Lions club involves international dues plus a charter or entrance fee, and the current amounts are in the Membership Dues and Fees Chart (TK-40) on lionsclubs.org. Your club will tell you its own local dues. There are discounts: students aged 30 and younger pay half the international dues and have the charter or entrance fee waived; family membership gives a 50% discount on international dues for up to four family members in the same household who join the same club as a full-paying member; and Leo-Lions get 50% off international dues and a fee waiver. Students over 30 joining a Campus Lions club pay a discounted charter or entrance fee of US$10.00 and full international dues.", "facts": ["Current amounts: Membership Dues and Fees Chart (TK-40) on lionsclubs.org", "Student members (30 and younger): half international dues, fee waiver", "Family membership: 50% off international dues for up to four household members", "Leo-Lion: 50% off international dues, fee waiver"], "tags": ["cost", "dues", "fees"], "related": ["membership-types"], "src": ["pg-stu", "pg-fam", "leo-lion", "pg-pay"]}, {"id": "pay-dues", "cat": "Finance", "level": "member", "title": "How a club pays its international dues", "questions": ["how do i pay dues", "how do i pay club dues", "how do i pay international dues", "how does a club treasurer pay dues", "how do i pay my dues online"], "answer": "The club treasurer pays in the Lion Portal: log in, choose My Club, then Club Statements, and select Pay with PayPal or Pay Now. If you pay by bank deposit instead, the Payment Instructions page lists the details for each country.", "facts": ["Canada has a pre-authorised debit agreement form, and India has a NEFT payment detail form", "Use the Exchange Rates page for the rate to apply when you pay in another currency", "The Unidentified Deposits list shows deposits that could not be matched to a club or district", "The Finance Resources page also links current membership dues and fees, online statements and the Suspension Policy"], "tags": ["pay", "payment", "dues", "treasurer", "statement", "paypal"], "related": ["join-cost"], "src": ["pg-pay", "pg-fin"]}, {"id": "report-service", "cat": "Service", "level": "member", "title": "How to report a service project", "questions": ["how do i report service", "how do i report a service project", "how to report service activities", "when do i report service", "why report service"], "answer": "Report each service activity in the Lion Portal as soon as possible after you complete it. The Lion year ends on June 30, but reports for that year can still be entered until July 31. The Service Activity Information resource helps you collect what you need, including the list of global causes and project types.", "facts": ["Clubs that report service become eligible for the Kindness Matters Service Award and the Excellence Awards", "Reporting shows the club's impact, inspires new members and helps leaders guide service", "In the last fiscal year Lions and Leos, with LCIF support, improved the lives of 410 million people"], "tags": ["report", "service", "reporting", "portal", "activity"], "related": ["global-causes", "titles-club"], "src": ["pg-svc"]}, {"id": "insurance", "cat": "Legal", "level": "member", "title": "Insurance for Lions clubs and events", "questions": ["are lions clubs insured", "how do i get insurance for an event", "lions liability insurance", "do lions have insurance", "insurance for a club event", "what insurance do lions clubs have"], "answer": "All Lions clubs and districts are automatically covered by the association's Commercial General Liability program, worldwide. You can produce your own certificate of insurance as evidence of that cover, for example when a venue asks for one.", "facts": ["Certificate of insurance: there is a printable online version for the U.S. (2026-2027) and request forms for the U.S., Canada and the rest of the world", "The program includes a General Liability booklet and a Self-Inspection Checklist (both revised 2025) for fundraising activities", "In the United States only, clubs and districts can add supplemental cover: Directors and Officers Liability, Crime/Fidelity, Additional Liability and Accident insurance", "Additional Liability sits on top of the US$1,000,000 that is provided automatically", "Questions: DSP Insurance Services, Inc., (847) 934-6100 or (800) 316-6705"], "tags": ["insurance", "liability", "certificate", "event", "coverage"], "related": ["titles-club"], "src": ["pg-ins", "pg-cert"]}, {"id": "matching-grant", "cat": "Grants", "level": "member", "title": "LCIF Matching Grants: amounts, deadlines and how to apply", "questions": ["what is a matching grant", "how do i apply for a matching grant", "matching grant amount", "matching grant deadlines", "how much is a matching grant", "lcif matching grant"], "answer": "A Matching Grant gives capital funding for Lions-initiated humanitarian service projects, with priority for equipment and infrastructure. Grants range from US$10,000 to US$150,000. Projects in developing countries can receive up to 75 percent of the total project budget, and in developed countries up to 50 percent.", "facts": ["Applications are considered by the LCIF Board of Trustees three times a year, in August, January and May", "Application deadlines are February 1, May 1 and October 1: apply well before them", "The grant administrator must send LCIF a final report within 45 days of finishing the project", "Examples: schools and orphanages, facilities for people with disabilities, charitable medical facilities"], "tags": ["matching grant", "grant", "lcif", "capital", "apply"], "related": ["lcif", "global-causes"], "src": ["pg-mg"]}, {"id": "start-leo-club", "cat": "Leo", "level": "member", "title": "How to start a Leo club", "questions": ["how do i start a leo club", "how do i sponsor a leo club", "what does it cost to start a leo club", "what are leo club types", "what are alpha and omega leos"], "answer": "A Lions club sponsors a Leo club. First choose a Leo club advisor and decide the type: a community-based club open to any eligible young person, or a school-based club run in a school with extra leadership from school staff. Then choose the track by age: Alpha Leos are 12 to 18 and Omega Leos are 18 to 30.", "facts": ["Fees: a one-time organisation fee starting at US$100 and an annual Leo club sponsor levy of US$100, both of which may increase", "The Leo Club Starter Guide explains how to choose an advisor and lists the steps", "Leo members pay no membership fee"], "tags": ["leo", "start", "sponsor", "alpha", "omega", "advisor"], "related": ["leo-clubs", "leo-lion"], "src": ["pg-leo"]}, {"id": "student-join", "cat": "Joining", "level": "member", "title": "Joining Lions as a student", "questions": ["can i join as a student", "student membership discount", "how do students join lions"], "answer": "Yes. Students aged 30 and younger can join or charter any type of club at a discount: they pay half the international dues and the charter or entrance fee is waived. Campus Lions clubs are open to any student, full-time or part-time, living on or off campus.", "facts": ["Students over 30 joining a campus Lions club pay a discounted charter or entrance fee of US$10", "A student member certification worksheet confirms eligibility"], "tags": ["student", "campus", "discount", "join"], "related": ["join-cost", "campus-club", "membership-types"], "src": ["pg-stu"]}, {"id": "recruit-members", "cat": "Membership", "level": "member", "title": "How to recruit new members", "questions": ["how do i recruit members", "how do i recruit new members", "how to get new members for my club", "member recruitment steps", "how to attract members to a lions club"], "answer": "Recruitment is something every member can do, in four steps: 1) Just ask: invite friends, family, colleagues or neighbours you think would make good Lions, because a personal invitation is one of the most effective ways to bring in members. 2) Advocate for your club: talk about its impact and share personal stories. 3) Engage prospects directly: have a real conversation about how they can make a difference, and connect them with service that matches their interests. 4) Promote your service on social media: share photos and invite people to upcoming events.", "facts": ["The Just Ask! New Member Recruiting Guide and quick tips are on the Club Membership Chairperson page", "Run a new member orientation and induction ceremony once someone joins", "Clubs can also add members through a club branch or a family or student membership"], "tags": ["recruit", "recruitment", "new members", "invite", "grow"], "related": ["join-cost", "student-join", "gma"], "src": ["pg-rec", "pg-mem"]}, {"id": "start-new-club", "cat": "Membership", "level": "member", "title": "How to start a new Lions club", "questions": ["how do i start a new club", "how do i start a new lions club", "how to charter a new club", "steps to start a new lions club", "how to form a lions club"], "answer": "Follow these steps: 1) Read the New Club Development Guide and, if you can, attend or host a New Club Development Workshop. 2) Build a team and work with the new club's Guiding Lion. 3) Assess community needs with the Community Needs Assessment. 4) Promote the club and recruit members, for example with the Hello Brochure and a Just Ask! workshop. 5) Hold an informational night meeting and an organizational meeting. 6) Complete the application documents: the Charter Application Worksheet, charter member applications and the Report of Charter Members, then report the club in the Lion Portal. 7) Celebrate with a charter night, where the club receives its charter.", "facts": ["Districts can get Membership Development Grants and New Voices Grants towards club development costs", "The Membership Dues and Fees Chart shows current dues and fees for charter members", "Lions who help charter a club can earn Extension Awards"], "tags": ["start", "new club", "charter", "chartering", "form a club"], "related": ["club-branch", "recruit-members"], "src": ["pg-new"]}, {"id": "district-governor-role", "cat": "District leaders", "level": "member", "title": "What a district governor does", "questions": ["what is a district governor", "what does a district governor do", "district governor role", "district governor responsibilities", "role of dg"], "answer": "The district governor is Lions International's chief representative in the district. The governor leads membership growth, new club development and club retention, oversees the district Global Action Team, guides the district goals and promotes leadership and skills training.", "facts": ["Makes sure clubs follow association guidelines and remain in good standing", "Leads key meetings and conventions and builds teamwork across the district", "Supports LCIF initiatives", "Governors serve one year; a past district governor cannot be elected governor or vice district governor again"], "tags": ["district governor", "dg", "governor"], "related": ["titles-district"], "src": ["pg-dg"]}, {"id": "club-president-role", "cat": "Club officers", "level": "member", "title": "What the club president and vice president do", "questions": ["what does a club president do", "what does the club president do", "what does a vice president do", "club president responsibilities"], "answer": "The club president and vice president oversee club operations, preside over board meetings and lead the club's Global Action Team. Their responsibilities include appointing qualified leaders, following constitutional and legal requirements, guiding and supporting members, and working with district teams on initiatives.", "facts": ["The key reference is the Standard Club Constitution and By-Laws", "The Club Officer Guide describes every officer's role", "Keeping Lion Portal reporting current is part of every club officer's job"], "tags": ["president", "vice president", "club officer"], "related": ["titles-club"], "src": ["pg-club"]}, {"id": "club-secretary-role", "cat": "Club officers", "level": "member", "title": "What the club secretary does", "questions": ["what does a club secretary do", "what does the club secretary do", "club secretary responsibilities", "secretary role in a lions club"], "answer": "The club secretary is the link between the club, the district and Lions International. The secretary keeps accurate records, such as meeting minutes, attendance and financial documents, and helps create the club calendar.", "facts": ["Supports smooth operations and member engagement", "Reporting membership and officers in the Lion Portal is normally a secretary task", "See the Club Officer Guide for the full role"], "tags": ["secretary", "minutes", "records"], "related": [], "src": ["pg-club"]}, {"id": "club-treasurer-role", "cat": "Club officers", "level": "member", "title": "What the club treasurer does", "questions": ["what does a club treasurer do", "what does the club treasurer do", "club treasurer responsibilities", "treasurer role in a lions club"], "answer": "The club treasurer handles the club's finances: collecting and depositing funds, working with the secretary to send members their dues statements, and reporting payments to the board. The treasurer pays bills as approved, keeps all financial records, and gives the board monthly and semi-annual financial updates.", "facts": ["Pays the club's international dues in the Lion Portal (My Club, Club Statements)", "Best Practice for Financial Transparency is a recommended resource"], "tags": ["treasurer", "finances", "funds"], "related": ["pay-dues"], "src": ["pg-club", "pg-pay"]}, {"id": "lions-year", "cat": "Basics", "level": "both", "title": "When the Lions year runs", "questions": ["when does the lions year start", "when does the lions year end", "what is the lions year", "lions fiscal year", "when do officers take office"], "answer": "The Lions year (fiscal year) runs from July 1 to June 30. Officers' terms follow that year. Service for a year can still be reported in the Lion Portal until July 31.", "facts": ["Dues are paid per half-year, based on June and December membership reports", "International officers are elected at the annual International Convention"], "tags": ["year", "fiscal", "july", "june"], "related": ["report-service"], "src": ["pg-svc"]}, {"id": "history", "cat": "history", "level": "general", "title": "A short history of Lions", "questions": ["what is the history of lions", "history of lions clubs", "who founded lions clubs", "when was lions clubs international founded", "when did lions start", "lions history timeline", "who started lions", "who started the lions club"], "answer": "Lions began in 1917, when a Chicago businessman named Melvin Jones invited business clubs from around the USA to a meeting where the Association of Lions Clubs was formed. It became international in 1920 with the Border Cities Lions Club in Windsor, Canada. In 1925 Helen Keller challenged Lions to become knights of the blind. Leos were introduced in 1957, Lions Clubs International Foundation (LCIF) was created in 1968, and Lions welcomed their millionth member in 1973. Lions turned 100 in 2017, and today there are more than 1.4 million members in about 50,000 clubs.", "facts": ["1917: founded in Chicago by Melvin Jones", "1920: first club outside the USA, in Windsor, Canada", "1925: Helen Keller's challenge to Lions", "1945: Lions help establish the NGO section of the United Nations", "1957: Leo program begins", "1968: LCIF created", "1973: one millionth member", "1990: SightFirst launched", "2017: Lions turn 100 (Centennial Convention, Chicago)"], "tags": ["history", "founder", "melvin jones"], "related": ["helen-keller", "what-is-lions"], "src": ["mission-history"]}, {"id": "helen-keller", "cat": "history", "level": "general", "title": "Helen Keller and Lions", "questions": ["who was helen keller", "helen keller and lions", "knights of the blind", "why is helen keller important to lions", "helen keller day"], "answer": "Helen Keller was born in Tuscumbia, Alabama, USA, in 1880 and became blind and deaf after a fever at 18 months. She became a tireless advocate for people with disabilities. In 1925 she attended the Lions Clubs International Convention and challenged Lions to become knights of the blind in the crusade against darkness. Lions accepted, and their work ever since has included sight programs aimed at preventable blindness. In 1971 the International Board declared June 1 as Helen Keller Day.", "facts": ["1925: the challenge was made at the International Convention in Cedar Point, Ohio, USA", "June 1 is Helen Keller Day; Lions run sight-related service projects that day"], "tags": ["helen keller", "vision"], "related": ["cause-vision", "history"], "src": ["pg-helen", "mission-history"]}, {"id": "governing-documents", "cat": "clubrules", "level": "general", "title": "Constitution and by-laws: where to read the official documents", "questions": ["where can i find the constitution", "international constitution and by-laws", "district constitution and by-laws", "multiple district constitution", "lions constitution and by laws", "where are the lions governing documents", "board policy manual"], "answer": "Lions' governing documents are published by Lions Clubs International on lionsclubs.org, in the Resource Center under Governance: the Standard Form Lions Club, District and Multiple District Constitution and By-Laws, and the International Constitution and By-Laws. The Board Policy Manual is on the Legal Resources page. This guide explains the standard club constitution; for the district, multiple district and International documents, open the official PDF.", "facts": ["Open the Resource Center and filter by Governance", "Board Policy Manual and Legal Resources: lionsclubs.org"], "tags": ["constitution", "by-laws", "governance"], "related": [], "src": ["rc-library", "pg-legal", "la2"]}, {"id": "titles-club", "cat": "titles", "level": "club", "title": "Club leadership roles", "questions": ["what positions are there in a lions club", "lions club officer titles", "club officer titles", "who runs a lions club", "what are the roles in a lions club", "club positions"], "answer": "The officers of a Lions club are the president, immediate past president, vice president(s), secretary, treasurer, membership chairperson, service chairperson and marketing chairperson. The board of directors also includes the club LCIF coordinator, program coordinator, directors, and optionally a Lion tamer, tail twister and safety officer, plus a branch president and Leo advisor where there is one. The Member Resource Center has an official guide for each officer role.", "facts": ["Club Officer Guide: lionsclubs.org Managing Your Club page", "Role pages: Club President and Vice President, Club Secretary, Club Treasurer, Club Membership Chairperson, Club Service Chairperson, Club Marketing Communications Chairperson"], "tags": ["officers", "club"], "related": ["governing-documents"], "src": ["la2", "pg-club", "pg-mem", "pg-mkt"]}, {"id": "titles-zone-region", "cat": "titles", "level": "zone-region", "title": "Zone and region chairpersons", "questions": ["what does a zone chairperson do", "what does a region chairperson do", "zone chairperson role", "region chairperson role", "zone and region chairperson"], "answer": "Zone and region chairpersons support clubs within a district. The Zone and Region Chairperson Center on lionsclubs.org gathers their tools: the Zone Chairperson Learning Map, the Global Membership Approach resources, a zone meeting PowerPoint, the District Governor's Advisory Committee meeting report, meeting preparation checklist, minutes template and evaluation, and webinars such as The Successful Zone Chairperson. Open the page for the full set.", "facts": ["Zone Chairperson Workshop is available in the Lions Learning Center", "Club visit and club health resources are on the same page"], "tags": ["zone", "region"], "related": ["structure"], "src": ["pg-zone"]}, {"id": "global-action-team", "cat": "titles", "level": "district", "title": "The Global Action Team (GAT)", "questions": ["what is the global action team", "what is gat", "what is the global leadership team", "what is the global membership team", "what is the global extension team", "what is a gmt coordinator", "what is a district gmt coordinator", "what is glt"], "answer": "The Global Action Team (GAT) is a network of Lions at every level who help districts reach their MISSION 1.5 targets, which means growing club membership, building leaders and raising Lions' visibility through service. It has four teams: the Global Membership Team (GMT), which recruits members and promotes good member experiences; the Global Extension Team (GET), an offshoot of GMT that starts new clubs in the district; the Global Leadership Team (GLT), which develops Lion and Leo leaders; and the Global Service Team (GST), which helps clubs improve their service projects and use Lions and LCIF programs and grants. Each team has coordinators, and the district governor oversees the district's GAT.", "facts": ["MISSION 1.5 is the drive to reach 1.5 million members worldwide by July 1, 2027", "Coordinator role descriptions and annual checklists are on each team's toolbox page", "A Global Action Team course is in the Lions Learning Center"], "tags": ["gat", "gmt", "glt", "gst", "get"], "related": ["titles-district"], "src": ["pg-gat", "pg-gatr", "pg-gmt", "pg-glt", "pg-gst"]}, {"id": "club-constitution", "cat": "clubrules", "level": "club", "title": "Club constitution and by-laws: the overview", "questions": ["club constitution", "what is the club constitution", "what are the club by-laws", "standard club constitution and by-laws", "what does the club constitution cover", "lions club constitution"], "answer": "The Standard Club Constitution and By-Laws is the rule book a Lions club follows. The constitution covers the club's name, purposes, membership, emblem, colours, slogan and motto, supremacy, club size, officers, board of directors, delegates, club branches, club funds and amendments. The by-laws cover membership categories, good standing, elections, duties of officers, board positions, committees, meetings, fees and dues, club branch administration, miscellaneous rules and the dispute resolution procedure. Lions Clubs International publishes it in the Resource Center on lionsclubs.org.", "facts": ["Version used here: LA-2, revised October 6, 2026", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["constitution", "by-laws"], "related": ["club-supremacy", "club-membership-categories"], "src": ["la2"]}, {"id": "club-supremacy", "cat": "clubrules", "level": "club", "title": "Which rules come first: club, district or International?", "questions": ["which rules come first club district or international", "supremacy of the international constitution", "what if club by-laws conflict with the district constitution", "does the international constitution override club by-laws"], "answer": "The standard club constitution and by-laws govern the club unless they are amended in a way that conflicts with the district (single, sub- or multiple) and International constitutions and with Lions Clubs International policies. If the club's rules conflict with the district's, the district's constitution and by-laws govern. If they conflict with the International constitution and by-laws or Board Policy, those govern.", "facts": ["Order of authority: International constitution and Board Policy, then district, then club", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["supremacy"], "related": ["club-constitution"], "src": ["la2"]}, {"id": "club-purposes", "cat": "values", "level": "club", "title": "The purposes of Lions Clubs International and of a club", "questions": ["what are the purposes of lions clubs international", "what are the purposes of a lions club", "purposes of lions", "what is the vision statement of lions", "lions vision and mission statement", "what are the lions objects", "what are the objects of lions clubs"], "answer": "Lions Clubs International has eight purposes: to organize, charter and supervise Lions clubs; to coordinate their activities and standardize administration; to create and foster a spirit of understanding among the peoples of the world; to promote good government and good citizenship; to take an active interest in the civic, cultural, social and moral welfare of the community; to unite clubs in friendship, good fellowship and mutual understanding; to provide a forum for open discussion of matters of public interest, except that partisan politics and sectarian religion are not debated by members; and to encourage service-minded people to serve without personal financial reward and to promote high ethical standards. The vision is to be the global leader in community and humanitarian service.", "facts": ["A club's own purposes (Article II) repeat these, without the first two about organizing and coordinating clubs", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["purposes", "vision", "mission"], "related": ["mission-vision", "code-of-ethics"], "src": ["la2"]}, {"id": "club-motto-colors", "cat": "values", "level": "club", "title": "Lions motto, slogan and colours", "questions": ["what is the lions motto", "lions motto", "what is the lions slogan", "what colors do lions use", "lions colours", "what does lions stand for", "what does the word lions stand for"], "answer": "The Lions motto is We Serve. The slogan is Liberty, Intelligence, Our Nation's Safety, which is where the letters of LIONS come from. The colours of the association and of every chartered club are purple and gold.", "facts": ["Motto: We Serve", "Slogan: Liberty, Intelligence, Our Nation's Safety", "Colours: purple and gold", "Use of the name and emblem follows the association's guidelines", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["motto", "slogan", "colors"], "related": ["logo-brand"], "src": ["la2"]}, {"id": "club-membership-eligibility", "cat": "clubrules", "level": "club", "title": "Who can be a member, and how are members admitted?", "questions": ["who can become a lions member", "eligibility for lions membership", "how are members admitted", "membership by invitation", "how do i become a member of a lions club", "can anyone join lions", "what are the membership eligibility rules", "membership requirements", "how many members does a club need", "minimum members to charter a lions club", "how many members to start a lions club"], "answer": "Any person of legal age, good moral character and good reputation in their community may be granted membership. Membership is by invitation only: a member in good standing sponsors the nominee, the nomination goes to the membership chairperson or club secretary, the membership committee investigates, and the board of directors approves it by majority vote. The signed membership form, entrance fee and dues must reach the secretary before the member is reported to Lions Clubs International and officially recognised. A club should aim to keep 20 members, the minimum needed for a charter.", "facts": ["Expulsion for cause needs a two-thirds vote of the entire board of directors", "Expelled members lose the right to use the Lions name and emblem", "Club size: aim for 20 members", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["eligibility", "admission"], "related": ["club-membership-categories", "join-cost"], "src": ["la2"]}, {"id": "club-membership-categories", "cat": "clubrules", "level": "club", "title": "Membership categories: Active, Honorary, Life and more", "questions": ["membership categories", "what are the membership categories", "what is a life member", "what is an honorary member", "what is an affiliate member", "what is an associate member", "what is a privileged member", "what is a member at large", "what is a discounted member", "active member rights", "types of members in a lions club", "all types of club members", "what types of members are in a lions club"], "answer": "The standard by-laws list eight categories. Active members have all rights, including voting and holding office, and must attend, pay dues promptly, take part and reflect well on the club. Member-at-Large is for a member who has moved or cannot attend regularly; the board reviews it every six months, and they cannot hold office or vote at district or international meetings. Honorary is for a non-member with outstanding service, and the club pays their fees. Privileged is for a Lion of 15 or more years who must give up active status; they can vote but not hold office. Life membership is for 20 or more years of active membership with outstanding service (also for a critically ill member, or 15 or more years and age 70 or over), with a one-time US$650 payment by the club. Associate is held by someone whose primary club is elsewhere. Affiliate is for someone who supports the club but cannot fully take part. Discounted is for family, student or other discounted-dues members, who have all active rights.", "facts": ["Honorary members cannot exceed 5% of total membership; Affiliate members cannot exceed 25%", "Associate and Affiliate members may vote on club matters in person but cannot be delegates, hold office or serve on committees", "Honorary and Associate members are not counted in the delegate formula", "Exhibit A of the by-laws is the membership category chart", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["membership categories", "life member", "honorary", "affiliate"], "related": ["membership-types", "club-membership-eligibility"], "src": ["la2"]}, {"id": "club-good-standing", "cat": "clubrules", "level": "club", "title": "Good standing, resignation, transfer and reinstatement", "questions": ["what is good standing", "good standing for a club member", "how do i resign from my lions club", "how do i transfer to another lions club", "reinstatement of membership", "what happens if a member does not pay dues", "can i be a member of two lions clubs", "dual membership", "how can a member be removed"], "answer": "A member who does not pay a club debt within 30 days of the secretary's written notice loses good standing until it is paid; only members in good standing may vote or hold office. If the debt is still unpaid 60 days after notice, the secretary gives the board the member's name and the board decides whether to drop or keep them. A member may resign, effective when the board accepts it, and the board can withhold acceptance until debts are paid and club property returned. A dropped member in good standing may be reinstated by the board; after more than 12 months the full admission process applies again. A club may accept a transfer from a member in good standing of another club, with the same 12-month rule. Nobody may hold membership in two Lions clubs at once, except honorary or associate membership. A member can be expelled for cause by a two-thirds vote of the entire board.", "facts": ["Dues debts: 30 days to lose good standing, 60 days for the board to decide", "Transfer: the secretary must complete the transfer form without delay unless the board is withholding acceptance over debts", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["good standing", "resignation", "transfer"], "related": ["club-membership-categories"], "src": ["la2"]}, {"id": "club-officers", "cat": "clubrules", "level": "club", "title": "Club officers and what they do", "questions": ["who are the club officers", "what are the club officers", "club officers duties", "officers of a lions club", "how are club officers removed"], "answer": "The officers of a club are the president, immediate past president, vice president(s), secretary, treasurer, membership chairperson, service chairperson and marketing chairperson. The president is chief executive officer, presides at board meetings and chairs the club Global Action Team. The immediate past president and other past presidents mentor the president and vice presidents, and the immediate past president serves as club LCIF coordinator unless another Lion is appointed. The first vice president serves as leadership chairperson. The secretary is the liaison to the district and the association, keeps records and files reports. The treasurer receives and pays out club money and prepares financial reports. The membership, service and marketing chairpersons lead those committees. An officer can be removed for good cause by a two-thirds vote of the entire club membership.", "facts": ["Officers are elected annually and take office on July 1", "Each officer's detailed duties are in Article III of the by-laws", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["officers"], "related": ["club-president-role", "club-secretary-role", "club-treasurer-role", "club-board"], "src": ["la2"]}, {"id": "club-board", "cat": "clubrules", "level": "club", "title": "Board of directors: members, quorum and powers", "questions": ["what does the club board of directors do", "what is the club board of directors", "who is on the club board", "what do club directors do", "what is a club director", "board of directors quorum", "club board quorum", "how many directors does a lions club have", "role of directors in a lions club"], "answer": "The board of directors is made up of the club officers, the Lion tamer and tail twister (both optional), the club LCIF coordinator, the program coordinator, a safety officer (optional), the branch president if there is a branch, a Leo advisor if designated, and all other elected directors and chairpersons. It is the executive board of the club: it shapes all new business and policy before the members approve it, authorizes all spending, may modify or override an officer's action, has the books audited every year, appoints the bank and the surety for bonded officers, and keeps at least two separate funds. A majority of directors in person is a quorum. A director provides extra oversight of items before the board and serves a two-year term, with half of the directors elected each year.", "facts": ["The board may not create debt beyond the club's current income", "Net income from fundraising from the public may not be spent on administration", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["board", "directors", "quorum"], "related": ["club-board-positions", "club-funds"], "src": ["la2"]}, {"id": "club-board-positions", "cat": "clubrules", "level": "club", "title": "Other board positions: LCIF coordinator, safety officer, Lion Tamer, Tail Twister", "questions": ["what is a tail twister", "what does the tail twister do", "what is a lion tamer", "what does the lion tamer do", "what is a club lcif coordinator", "what is a safety officer", "what is a program coordinator", "what does the program coordinator do"], "answer": "The program coordinator schedules speakers and entertainment for general meetings. The club LCIF coordinator promotes LCIF and its mission and works with the district LCIF coordinator. The safety officer (optional) checks activities for hazards, completes the self-inspection checklist from Lions Clubs International, ensures supervision and insurance, and reports incidents to the insurer. The Lion tamer (optional) looks after club property such as flags, banners, gong and gavel, acts as sergeant-at-arms and makes sure each new member sits with a different group at each meeting. The tail twister (optional) promotes harmony and fun at meetings and may impose fair, good-natured fines, which go into the club's administrative fund.", "facts": ["Directors serve two-year terms", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["tail twister", "lion tamer", "lcif coordinator"], "related": ["club-board"], "src": ["la2"]}, {"id": "club-elections", "cat": "clubrules", "level": "club", "title": "Club elections: nominations, voting and vacancies", "questions": ["how are club officers elected", "how are officers elected", "club elections", "when are club elections held", "who can be nominated for club office", "how are vacancies filled", "how long is a club officer term", "nomination committee"], "answer": "Officers are elected every year and take office on July 1 for one year. Half of the directors are elected each year for two-year terms. Only active members in good standing can hold office. The president appoints a nominating committee, which proposes candidates at a nomination meeting held in March (or as the board decides), where nominations can also be made from the floor. The election is held in April (or as the board decides) by secret written ballot, with no nominations from the floor at the election. A candidate needs a majority of valid votes cast; if nobody has one, the lowest candidate is dropped and voting continues. Both meetings need at least 14 calendar days' notice. The secretary reports new officers to the International Office within 15 days. If the president or a vice president post becomes vacant, the vice presidents move up by rank; other vacancies are filled by board appointment.", "facts": ["Notice for nomination and election meetings: at least 14 calendar days", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["elections", "nominations"], "related": ["club-officers"], "src": ["la2"]}, {"id": "club-meetings", "cat": "clubrules", "level": "club", "title": "Club meetings: types, notice, quorum and voting", "questions": ["what is a quorum", "what is a quorum at a club meeting", "what is the quorum for a club meeting", "how often do clubs meet", "how many meetings should a club hold", "special club meeting notice", "can a club meet online", "what happens at a lions meeting", "what happens at a lions club meeting", "how to conduct a club meeting", "how do i run a board meeting", "how do i conduct a board meeting", "how do i run an effective meeting", "what is the order of business at a meeting"], "answer": "The board sets its meeting times; monthly board meetings are recommended, and the president or any three board members can call a special board meeting. A club is encouraged to hold at least one meeting, event or service activity a month, and a service project can replace a meeting. The president can call a special club meeting, must call one if the board asks, and members get at least 10 days' notice stating the purpose, time and place. An annual meeting closes each Lions year, with final reports read and new officers installed. Meetings can be held by teleconference or web conference. A quorum is a majority of members in good standing in person, and a majority of members present decides. Business by mail or electronic means needs written approval of two-thirds of the entire club. Questions of procedure follow Robert's Rules of Order, Newly Revised.", "facts": ["Charter night anniversary meeting may be held each year", "The by-laws set no fixed agenda: the club decides its own order of business", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["meetings", "quorum"], "related": ["club-board"], "src": ["la2"]}, {"id": "club-committees", "cat": "clubrules", "level": "club", "title": "Standing committees of a club", "questions": ["what committees does a lions club have", "standing committees of a club", "what is the global action team in a club", "what is the club global action team", "what does the finance committee do", "how are club committees formed", "what is the leadership committee", "what is the membership committee"], "answer": "The president may appoint these standing committees: Global Action Team (chaired by the president, with the first vice president as leadership chairperson, and the membership and service chairpersons, supported by the marketing chairperson), Constitution and By-Laws, Finance (chaired by the treasurer), Membership, Marketing, Service, Information Technology, and Leadership (chaired by the first vice president). The president can appoint special committees with board approval and is an ex-officio member of every committee. Each committee should report to the board monthly.", "facts": ["Chairpersons who sit on the board must be elected", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["committees", "global action team"], "related": ["global-action-team"], "src": ["la2"]}, {"id": "club-fees", "cat": "clubrules", "level": "club", "title": "Entrance fees, dues and fiscal year", "questions": ["what is the entrance fee", "how do club dues work", "how are club dues set", "what is the fiscal year of a lions club", "club dues and fees", "who sets club dues"], "answer": "Each new, reinstated or transfer member pays an entrance fee that includes the current association entrance fee, collected before the secretary reports the member to Lions Clubs International. The board may waive part of the club portion for transfers or reinstatements within 12 months. Annual dues are set by the members at the annual meeting for each category (Active, Member-at-Large, Honorary, Privileged, Life, Associate, Affiliate, Discounted) and include international and district dues, which the treasurer remits. The fiscal year runs July 1 to June 30.", "facts": ["Dues are paid in advance at times the board decides", "The club sets its own amounts; the by-laws leave them blank", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["dues", "fees"], "related": ["join-cost"], "src": ["la2"]}, {"id": "club-funds", "cat": "clubrules", "level": "club", "title": "Club funds: public funds and administrative funds", "questions": ["how are club funds handled", "public funds and administrative funds", "what is an activity fund", "what is an administrative fund", "what can club money be spent on", "what is the administration fund", "what is the administrative fund"], "answer": "A club keeps at least two separate funds. Administrative funds come from dues, fines and member contributions. Public (activity) funds are raised by asking the public for support, and they must go back to public use, including any interest. Only the direct operating costs of the fundraising activity may be deducted, and net income from public fundraising may not pay administrative costs. The board authorizes all spending, appoints the bank, and has the books audited annually.", "facts": ["The treasurer prepares monthly and semi-annual financial reports for the board", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["funds"], "related": ["club-treasurer-role", "club-board"], "src": ["la2"]}, {"id": "club-amendments", "cat": "clubrules", "level": "club", "title": "Amending the club constitution and by-laws", "questions": ["how to amend the club constitution", "how do we change the club by-laws", "how to amend club by-laws", "amending the constitution"], "answer": "The constitution can be amended at a regular or special club meeting with a quorum, by a two-thirds vote of members present and voting, once the board has considered the amendment. The by-laws can be amended or repealed by a majority of members present and voting. In both cases the proposed amendment must be sent in writing to every member at least 14 calendar days before the vote.", "facts": ["This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["amendments"], "related": ["club-constitution"], "src": ["la2"]}, {"id": "club-branch-rules", "cat": "clubrules", "level": "club", "title": "Club Branch: rules in the constitution", "questions": ["club branch rules", "how does a club branch work", "club branch officers", "club branch dues", "can a club branch be dissolved"], "answer": "A club may form a branch to extend Lionism where a chartered club is not practical. Branch members are members of the parent club, in any category, and the branch meets as part of the parent club and serves its community. Branch members elect a president, secretary and treasurer; with the parent club's liaison, who is the branch's fourth officer, they form the branch executive committee. The branch president sits on the parent club's board. Branch members vote on branch matters and count toward the parent club's quorum only when present in person. A branch may charge its own entrance fee and need not pay the parent club's dues. The parent club can disband the branch by majority vote of the entire membership, and leftover branch funds go back to the parent club.", "facts": ["This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["club branch"], "related": ["club-branch"], "src": ["la2"]}, {"id": "club-conduct", "cat": "clubrules", "level": "club", "title": "Politics, religion, pay and conduct rules", "questions": ["can a lions club endorse a political candidate", "can lions discuss politics or religion", "can a club officer be paid", "rules about personal benefit in lions", "can outsiders ask for money at a club meeting", "does a lions club use roberts rules"], "answer": "A club may not endorse or recommend any candidate for public office, and members may not debate partisan politics or sectarian religion at meetings. Members may not use membership to further personal, political or other aims, except their progress in Lionism. No officer is paid for official service, except that the board may fix a secretary's pay. People who are not members may not solicit funds during club meetings, and spending proposals are referred to a committee or the board. Procedure follows Robert's Rules of Order, Newly Revised.", "facts": ["This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["conduct", "politics", "religion"], "related": ["code-of-ethics"], "src": ["la2"]}, {"id": "club-delegates", "cat": "clubrules", "level": "club", "title": "Delegates to district and International conventions", "questions": ["what are club delegates", "how many delegates does a club get", "who votes at convention", "how are delegates chosen", "delegates to the international convention"], "answer": "For the International Convention a club has one delegate and one alternate for every 25 members, or major fraction (13 or more), and at least one of each. For a district or multiple district convention it has one delegate and one alternate for every 10 members enrolled at least a year and a day, or major fraction (5 or more), and at least one of each. The board or a designated committee names delegates, with the members' approval; they must be members in good standing entitled to vote. Each delegate present in person casts one vote for each office and each question.", "facts": ["Honorary and Associate members are not counted in the delegate formula", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["delegates", "convention"], "related": ["club-membership-categories"], "src": ["la2"]}, {"id": "club-disputes", "cat": "clubrules", "level": "club", "title": "Resolving disputes in a club", "questions": ["how are disputes resolved", "club dispute resolution", "what if there is a dispute in my lions club", "how to resolve a conflict in a lions club"], "answer": "Disputes between members, former members, the club or a board officer about membership, the club's constitution and by-laws, or expulsion, which cannot be settled by other means, are resolved under the Dispute Resolution Procedures set by the International Board of Directors. The club president is expected to encourage diplomacy and settle disputes fairly and transparently, using that procedure if needed.", "facts": ["This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["disputes"], "related": ["club-officers"], "src": ["la2"]}, {"id": "club-member-role", "cat": "clubrules", "level": "club", "title": "What a Lions club member does", "questions": ["what does a lions club member do", "what is the role of a club member", "what are the duties of a lions member", "member responsibilities in a lions club", "what is expected of a lion member", "rights and duties of a club member", "what are the obligations of a lions member"], "answer": "An active Lions club member has all the rights and privileges of membership, including the right to vote on all matters and to seek any office in the club, district or association if qualified. In return, members are expected to attend regularly, pay dues promptly, take part in club activities, and conduct themselves in a way that reflects well on the club in the community. Members are also encouraged to invite prospective members and to follow the Lions Code of Ethics.", "facts": ["Only members in good standing may vote or hold office", "Family, student, former Leo and young adult members who qualify are Active members with all rights", "This is the standard club form for FY 2026-27. Your club's own constitution and by-laws may differ: check your copy."], "tags": ["member", "duties"], "related": ["club-membership-categories", "club-officers", "code-of-ethics"], "src": ["la2"]}, {"id": "club-obligations", "cat": "clubrules", "level": "club", "title": "What every chartered club must do", "questions": ["what are the obligations of a chartered club", "duties of a lions club", "club obligations", "what does a lions club have to do to stay chartered"], "answer": "A chartered Lions club commits to a standard set of responsibilities. In practice these fall into four groups.\n\nRunning the club: meet or hold events on a regular schedule, keep members engaged, and settle internal disagreements through the official club dispute procedure.\n\nMoney and reporting: collect at least the minimum yearly dues needed to cover international and district charges and the club's own running costs, send a membership report to the International Office every month, and share financial details whenever they are requested.\n\nLeadership: elect officers every year, no later than April 15, so they can take office on July 1.\n\nIntegrity and service: check the background of each person proposed for membership, carry out projects that benefit the community and promote international understanding, follow International Board policies, uphold the Lions purposes and Code of Ethics, and protect the good name of the association.\n\nA club that neglects these duties can be placed in status quo.", "facts": ["Officers are elected by April 15 and start on July 1", "Membership is reported every month"], "tags": ["obligations", "good standing"], "related": ["club-good-standing", "club-status-quo", "club-elections"], "src": []}, {"id": "club-status-quo", "cat": "clubrules", "level": "club", "title": "Status quo: when a club is temporarily suspended", "questions": ["what is status quo for a lions club", "what does status quo mean", "club placed in status quo", "why is a club put in status quo", "what is protective status quo", "what happens to a club in status quo", "how does a club come out of status quo"], "answer": "Status quo is a temporary freeze on a club's charter, along with its rights, privileges and duties. It is used when a club is not functioning as a proper Lions club.\n\nTypical reasons: acting against the Lions purposes or behaving in a way that harms the association's reputation (for example, unresolved internal disputes or legal action); neglecting basic duties, such as not meeting or not sending membership reports for three or more months running; the club turns out to be inactive on paper only; or the members themselves ask to close or merge the club.\n\nWhile frozen, the club may not run service or fundraising projects, attend district, multiple district or international events, vote or nominate beyond the club, submit membership reports, sponsor a new club or start a Leo club.\n\nTo be restored, the club must correct the problem that caused the freeze, clear all outstanding amounts owed at district, multiple district and international level, and file a Reactivation Report listing any membership or leadership changes.\n\nProtective status quo is a separate case. When war, unrest, a natural disaster or a similar emergency prevents normal operation, the club is protected and may continue to function.", "facts": ["A status quo club that is not restored within 90 days can have its charter cancelled", "If a sponsoring Lions club is in status quo, its Leo club is affected too"], "tags": ["status quo", "suspension"], "related": ["club-obligations", "club-status-quo-process", "club-charter-cancellation"], "src": []}, {"id": "club-status-quo-process", "cat": "clubrules", "level": "district", "title": "How a club is recommended for status quo and helped back", "questions": ["how is a club put into status quo", "who can recommend status quo", "how does the district governor request status quo", "how are status quo clubs helped", "reactivation report for a club", "help a club in status quo"], "answer": "The district governor starts the process. To ask for a club to be placed in status quo for not meeting its duties, the governor needs the support of the first vice district governor and the zone chairperson, and must send documentation showing how the club is out of line with the constitution, by-laws or board policy, plus the steps the district team took to help it comply. The request must arrive at Lions Clubs International at least 90 days before the district or multiple district convention.\n\nThe goal is recovery, not punishment. As soon as a club is frozen, the district team (or the Coordinating Lion) begins working with it and keeps headquarters updated. If the club and district team agree, a Certified Guiding Lion can be appointed to coach it. The governor then reports in writing on progress, or recommends cancellation if the club cannot be revived. The Reactivation Report is co-signed by the first vice district governor and the zone chairperson.", "facts": [], "tags": ["status quo", "district governor"], "related": ["club-status-quo", "guiding-lion", "club-charter-cancellation"], "src": []}, {"id": "club-priority-status", "cat": "clubrules", "level": "district", "title": "Priority club status", "questions": ["what is priority club status", "what is a priority club", "what are priority clubs", "extra club visits by the district governor team", "how does a club get priority designation"], "answer": "Priority status is a support label that lets a district give extra attention to clubs that need it. It adds up to two more visits by the district governor team, paid from the existing governor budget, and does not change the club's standing, rights or duties.\n\nSome clubs qualify automatically: those chartered within the past 24 months, clubs in status quo or financial suspension, and clubs cancelled in the past 12 months that could be reinstated.\n\nA district governor can also nominate five other clubs. This requires an explanation of why help is needed, an action plan, and a Guiding Lion assigned to the club, with approval from the club, the governor and the first vice district governor. These clubs must still pay dues and meet their duties, and the designation can be withdrawn if there is no clear improvement within six months.", "facts": [], "tags": ["priority", "district"], "related": ["guiding-lion", "club-status-quo"], "src": []}, {"id": "club-financial-suspension", "cat": "clubrules", "level": "club", "title": "Financial suspension of a club", "questions": ["what is financial suspension", "when is a club financially suspended", "unpaid dues suspension", "club owes dues what happens", "how much unpaid dues leads to suspension", "payment plan for unpaid club dues"], "answer": "Suspension for unpaid dues is triggered when a club's overdue balance stays unpaid for more than 120 days and exceeds the lower of US$20 per member or US$1,000 for the club. The club's charter, rights, privileges and duties are then suspended. If good standing is not restored by the 28th of the following month, the charter is cancelled automatically.\n\nDuring suspension the club can still meet to plan its recovery, pay what it owes, or request an instalment plan. It cannot hold service or fundraising activities, join district events or seminars, endorse or nominate candidates, submit membership reports or sponsor new clubs.\n\nDistrict officers can often prevent a cancellation by urging the club to settle the balance or to agree a payment plan with the Finance Division at International Headquarters.", "facts": [], "tags": ["suspension", "dues"], "related": ["pay-dues", "club-charter-cancellation", "club-status-quo"], "src": []}, {"id": "club-charter-cancellation", "cat": "clubrules", "level": "club", "title": "Charter cancellation, mergers, name changes and club boundaries", "questions": ["how is a club charter cancelled", "why can a lions club charter be cancelled", "how to disband a lions club", "how do two lions clubs merge", "how to change the name of a lions club", "what are the boundaries of a lions club"], "answer": "A charter can end in three ways: the members vote to close the club (the district governor informs headquarters and confirms that all balances are paid); a status quo club is not reactivated within 90 days; or a financial suspension is not cleared in time. For areas with no district, Coordinating Lions make the recommendation.\n\nClubs that want to combine can merge. The district governor files the Merger Request form (DA-979), and the new club can request a merger certificate. To rename a club, the club submits the Name Change Request form (DA-980). Both forms can be found by searching the form code on lionsclubs.org.\n\nA club's territory is the municipality, or equivalent local government area, where it is based.", "facts": ["Merger form DA-979; name change form DA-980"], "tags": ["cancellation", "merger"], "related": ["club-status-quo", "club-financial-suspension", "club-transfer"], "src": []}, {"id": "club-transfer", "cat": "clubrules", "level": "district", "title": "Moving a club to another district", "questions": ["can a club change district", "single club transfer", "how to transfer a lions club to another district", "club moving to an adjacent district", "requirements for transferring a club"], "answer": "A club can switch to a neighbouring district through a simplified single-club transfer, provided district boundaries are not materially changed. The submission to Lions Clubs International should contain: club meeting minutes showing a majority approved the move; written consent from both district governors; minutes of both cabinets approving it; and a map showing the club's current and new location and the revised boundaries. Once approved, the transfer is effective straight away.", "facts": [], "tags": ["transfer", "district"], "related": ["redistricting", "club-charter-cancellation"], "src": []}, {"id": "guiding-lion", "cat": "clubrules", "level": "club", "title": "Guiding Lions and the Certified Guiding Lion program", "questions": ["what is a guiding lion", "what does a guiding lion do", "certified guiding lion course", "how to rebuild a weak club", "club rebuilding program", "how long is a guiding lion term"], "answer": "A Guiding Lion is an experienced member appointed to coach a club that is new, established or in need of rebuilding. The district governor makes the appointment for two years after consulting the club president, and one Guiding Lion can mentor at most two new clubs at once.\n\nTheir role is to help the club do well in its first two years, train officers and members, encourage growth and connect the club with resources.\n\nFor struggling established clubs, the Club Rebuilding Program gives governors flexibility to focus on recruiting, officer training and meaningful service. Supporting tools include a club planning guide, an assignment form (which also sets up the monthly Club Health Assessment) and a rebuilding checklist. Guiding Lions are encouraged to complete the Certified Guiding Lion course and to renew it every three years.", "facts": [], "tags": ["guiding lion", "club rebuilding"], "related": ["club-priority-status", "club-status-quo-process", "start-new-club"], "src": []}, {"id": "club-retention", "cat": "membership", "level": "club", "title": "Why members leave and how to keep them", "questions": ["why do members leave lions clubs", "how do we keep members", "member retention in a lions club", "why do members drop out", "how to stop members leaving"], "answer": "Members usually leave for a handful of reasons: friction and weak teamwork inside the club, meetings that drag or lack purpose, cliques or politics that make newcomers feel excluded, and having nothing meaningful to do.\n\nRetention is a shared effort led by the club president. What helps: keep meetings short and structured around a clear agenda; make sure every member, especially new ones, feels welcome; and involve members quickly in projects they care about, with chances to take on leadership.\n\nThe payoff is a club that is respected locally, can serve more people at home and abroad, and gives its members room to grow personally and professionally.", "facts": [], "tags": ["retention", "members"], "related": ["recruit-members", "lions-mentoring", "club-quality-initiative"], "src": []}, {"id": "club-quality-initiative", "cat": "clubrules", "level": "club", "title": "Club Quality Initiative (CQI)", "questions": ["what is the club quality initiative", "what is cqi", "how can my club improve", "how to plan change in a lions club", "club strategic planning tool", "what is lci forward"], "answer": "The Club Quality Initiative (CQI) is a structured way for a club to review itself and plan improvements. It can be run as one working session, a series of meetings or a half-day workshop.\n\nIt follows five steps:\n1. Understand how change happens and the LCI Forward framework, which sets direction for stronger service, operations and unity.\n2. Identify what needs to improve, using the assessments linked to LCI Forward.\n3. Set SMART goals.\n4. Turn goals into plans, ranking short- and long-term priorities and assigning them to committees or task forces.\n5. Put the plan into action and keep it going: set milestones with deadlines, report on them at every meeting and celebrate progress.", "facts": [], "tags": ["cqi", "planning"], "related": ["club-retention", "guiding-lion"], "src": []}, {"id": "year-round-growth", "cat": "membership", "level": "club", "title": "Year-round Growth Program (membership invitation awards)", "questions": ["what is the year round growth program", "membership excellence award", "sponsor new members award", "membership excellence banner patch", "how many members to get membership excellence patch"], "answer": "The Year-Round Growth Program rewards members and clubs for bringing in new people during the Lions year.\n\nFor individuals: anyone who sponsors a new member can receive a sponsorship certificate from the international president, and sponsoring three or more in a year earns the Membership Excellence lapel pin.\n\nFor clubs: a Membership Excellence banner patch goes to clubs that add 3 or more members (up to 21 members), 5 or more (22 to 40 members) or 8 or more (41 or more members). In each constitutional area, the best club in each size band, judged on new members and positive net growth, receives a Lions Clubs International flag set.\n\nA useful approach is to give each month its own target group: for example students and Leos early in the year, families toward year end, women members in late winter, and an induction ceremony in April.", "facts": [], "tags": ["growth", "awards"], "related": ["recruit-members", "induction-day", "gma"], "src": []}, {"id": "join-together", "cat": "membership", "level": "club", "title": "Join Together program", "questions": ["what is the join together program", "how can a group of people become a lions club", "join together lions", "can an existing group join lions", "bring a non profit into lions"], "answer": "Join Together is an invitation to existing community organizations to become part of Lions. A group of 15 or more people can become its own Lions club with a reduced flat charter fee of US$300. A group of five or more can become a branch of an existing Lions club, and new members pay no entrance fee.\n\nA partner organization needs to have been established for at least three years. The program supplies a new-club training course, a Start a New Club page, a presentation, a flyer and a partnership guide, and aims to collect success stories and feedback from the partner organizations.", "facts": [], "tags": ["join together", "new club"], "related": ["start-new-club", "club-branch", "club-types"], "src": []}, {"id": "induction-day", "cat": "membership", "level": "district", "title": "Lions Worldwide Induction Day", "questions": ["what is worldwide induction day", "lions induction day april", "when is lions worldwide induction day", "how to organize an induction ceremony", "new member induction ceremony"], "answer": "Lions Worldwide Induction Day is a coordinated celebration of new members. Every district holds an induction ceremony in April on the same day, ideally alongside a district or multiple district convention or other gathering. The aim is to boost recruitment and raise public awareness.\n\nDistricts decide the format: a single district event, or separate club and zone events. The ceremony can honor everyone inducted that year, feature a guest speaker, include a group service project or a reception, and invite local officials and media. Lions Clubs International supplies a planning guide, commemorative certificates for new members and press releases for club presidents.", "facts": [], "tags": ["induction", "new members"], "related": ["year-round-growth", "new-member-first-steps"], "src": []}, {"id": "redistricting", "cat": "structure", "level": "district", "title": "Redistricting: changing district boundaries", "questions": ["how does redistricting work", "how to redistrict a lions district", "minimum clubs and members for a district", "who approves redistricting", "merging districts", "what is needed to split a district"], "answer": "Any change to district boundaries must be approved by the International Board of Directors. That includes turning a single district into a multiple district, adding, splitting, combining or merging sub-districts, and moving boundaries. Proposals are due 60 days before the Board's October meeting.\n\nA proposal should include the list of clubs for each new sub-district (each must have at least 35 clubs and 1,250 members in good standing), a map of the new boundaries, certified minutes of the approving meetings and a US$500 fee. The Board needs only a simple majority to consider it.\n\nIf a multiple district merges sub-districts that fall below the 35-club / 1,250-member minimum, the same papers apply with no fee, and the multiple district convention must approve. If a multiple district changes district names or structure without altering sub-district lines, it needs two-thirds approval from cabinet members representing two-thirds of its districts.", "facts": ["Minimum 35 clubs and 1,250 members per sub-district"], "tags": ["redistricting", "district"], "related": ["club-transfer", "structure"], "src": []}, {"id": "dgac", "cat": "structure", "level": "district", "title": "District Governor's Advisory Committee", "questions": ["what is the district governor's advisory committee", "what does the dgac do", "who is on the advisory committee", "zone advisory committee lions"], "answer": "The District Governor's Advisory Committee is a zone-level body that supports the district governor and cabinet. The zone chairperson leads it, and its members are the presidents and secretaries of the clubs in the zone. The district membership, leadership and service coordinators (GMT, GLT, GST) may be invited to present opportunities.\n\nIts purpose is to help each club run effectively, follow the constitution, by-laws and policies, and meet the needs of its community.", "facts": [], "tags": ["advisory committee", "zone"], "related": ["titles-zone-region", "district-governor-role"], "src": []}, {"id": "talking-about-lions", "cat": "values", "level": "general", "title": "Talking about Lions: key messages and common questions", "questions": ["how do i explain lions to someone", "key messages about lions", "what do i say to the media about lions", "how to answer questions about lions", "why should i join lions instead of volunteering alone", "is lions membership declining", "how are lions relevant today"], "answer": "If you are speaking about Lions to the media, a school or a community group, these are the core messages to convey:\n\n- Lions Clubs International is the largest service club organization in the world and serves both locally and globally.\n- LCIF, the foundation, funds grants and programs, and donations go directly to them; Lions cover administrative costs through member dues.\n- Lions focus on global causes: childhood cancer, diabetes, disaster relief, the environment, hunger, vision and youth.\n- Lions are hands-on, from fundraising breakfasts to building wheelchair ramps.\n\nSuggested replies to common questions:\n- Who are Lions? Volunteers around the world working to improve their communities; women are the fastest-growing group.\n- What do they do? They respond to local needs, from helping people with vision loss and supporting youth to medical missions and disaster relief.\n- Why are Lions still relevant? There are still needs, and Lions keep answering them.\n- How do I join? Contact a local club or use the club locator on lionsclubs.org.\n- Why join rather than volunteer alone? A global network brings far more resources and impact than individuals can on their own.\n\nKeep the tone positive.", "facts": [], "tags": ["messages", "media"], "related": ["what-is-lions", "how-to-join", "logo-brand"], "src": []}, {"id": "lions-protocol", "cat": "values", "level": "club", "title": "Protocol: seating and precedence at Lions events", "questions": ["lions protocol", "head table seating", "where does the presiding officer sit", "order of precedence at lions events", "how to seat guests at a lions meeting", "national anthem at lions event"], "answer": "Protocol is about showing proper respect when seating and introducing people at Lions events.\n\nHead table: the person chairing the meeting takes the central seat. The main speaker sits in the second position, and other dignitaries follow by rank, balanced on both sides where possible. If there is a podium, the chair sits on the left of the podium as seen by the audience and the main speaker on the right. Spouses sit beside the member, on the member's left on the left side of the table and on the right on the right side.\n\nRecognition: someone with several titles is acknowledged by their highest one. Elected officers outrank appointed ones, and local custom applies to any extra positions. Melvin Jones Fellows are best acknowledged together, and their fellowship noted when they are introduced.\n\nAnthems: if representatives of the International Board from another country attend an event with national anthems, their country's anthem should be included.", "facts": [], "tags": ["protocol"], "related": ["titles-overview", "titles-district"], "src": []}, {"id": "lions-mentoring", "cat": "membership", "level": "member", "title": "Lions Mentoring Program", "questions": ["what is the lions mentoring program", "mentoring for new lions", "basic mentoring program", "advanced mentoring lions", "how long should new members take to complete mentoring"], "answer": "The Lions Mentoring Program supports each member's personal development so they can serve better and be ready for leadership. It has a basic and an advanced stage, each in two levels.\n\nBasic Level 1, the Responsibility of Being a Lion: who Lions are, their humanitarian vision, traditions, structure and what membership expects. New members should complete it in their first three months.\nBasic Level 2, Relationships: building working relationships and the skills needed for club leadership, ideally within six months.\nAdvanced Level 1, Results: accountability for outcomes through community projects, a stepping stone to club leadership.\nAdvanced Level 2, Replication: developing other leaders, which supports growth and can lead to district-level roles, and can be supplemented with district training.", "facts": [], "tags": ["mentoring", "new members"], "related": ["new-member-first-steps", "leadership-training"], "src": []}, {"id": "peace-poster", "cat": "youth", "level": "general", "title": "Peace Poster Contest", "questions": ["what is the peace poster contest", "who can enter the lions peace poster contest", "peace poster age limit", "how is the peace poster judged", "how do posters advance in the contest"], "answer": "The Peace Poster Contest invites young people to show, through art, what peace means to them. Clubs run it with local schools and youth groups. The theme is set each year. Students who are 11, 12 or 13 on November 15 may enter.\n\nEntries are judged on originality, artistic quality and how well they express the theme. Winners progress from local to district, multiple district and international levels, where a panel of experts from art, peace, youth, education and media selects one grand prize winner and 23 merit award winners.", "facts": [], "tags": ["peace poster", "youth"], "related": ["youth", "peace-essay"], "src": []}, {"id": "peace-essay", "cat": "youth", "level": "general", "title": "International Peace Essay Contest", "questions": ["what is the peace essay contest", "who can enter the lions essay contest", "essay contest for visually impaired students", "peace essay rules"], "answer": "The Peace Essay Contest is designed for young people who are visually impaired, giving them a way to express their ideas about peace. Lions partner with local schools and families to find participants.\n\nEligibility: visually impaired students aged 11, 12 or 13 on November 15. Each entry needs a completed entry form and must be written in English, typed in black ink, double-spaced and at most 500 words. The theme changes yearly and one grand prize winner is selected.", "facts": [], "tags": ["peace essay", "youth"], "related": ["peace-poster", "youth"], "src": []}, {"id": "lcif-donation-faq", "cat": "foundation", "level": "general", "title": "LCIF donations: common questions", "questions": ["difference between restricted and unrestricted donations", "how fast should lcif donations be sent", "does lcif use donations for administration", "when is melvin jones fellowship recognition sent", "can i donate stocks or property to lcif", "lcif donor reports"], "answer": "Which gifts help most? Unrestricted donations, because they support all LCIF programs. Restricted gifts go to specific funds, such as major disaster relief or a special campaign.\n\nDo donations pay for administration? No. LCIF's trustees require that its administrative and promotional costs be covered from investment income, so donations are used for grants.\n\nHow quickly should funds be sent? Without delay, so the donor's record is updated and recognition can be issued.\n\nWhen is recognition such as Melvin Jones Fellowship issued? Only after LCIF receives the donation, together with the required forms.\n\nAre reports available? Yes. District governors and district and multiple district LCIF coordinators get quarterly donation summaries and other reports.\n\nOther ways to give: stocks, securities, property and planned gifts are accepted. See lcif.org or contact LCIF staff.", "facts": [], "tags": ["lcif", "donations"], "related": ["lcif", "lcif-grants", "lcif-leaders"], "src": []}, {"id": "community-impact-grants", "cat": "Grants", "level": "general", "title": "District and Club Community Impact Grants", "questions": ["what is the district and club community impact grant", "how does a club earn a community impact grant", "minimum donation for a community impact grant", "what is dcg lcif"], "answer": "District & Club Community Impact Grants return part of LCIF's unrestricted donations (15 percent) to Lions for local projects.\n\nTo earn a grant, a club must contribute at least US$5,000, or a district at least US$10,000, within a fiscal year (July 1 to June 30). The grant can then be applied for in the next fiscal year.\n\nEarned funds can be used for local projects through an application, or as the local matching share in other LCIF grant applications. A club can keep its funds or release them to its district to add to the district account.", "facts": [], "tags": ["grants", "lcif"], "related": ["lcif-grants", "matching-grant"], "src": []}, {"id": "lions-pledges", "cat": "values", "level": "member", "title": "Pledges: new member, sponsor and rededication", "questions": ["what is the new member pledge", "what is the sponsors pledge", "what is the rededication pledge", "what does a new lion promise", "what does a sponsor promise"], "answer": "Lions use three short pledges at induction and renewal ceremonies.\n\nNew member's pledge: the new member accepts membership of their club and commits to take part in its activities, live by the Code of Ethics, attend meetings, take on tasks and contribute to the programs of the club, district and Lions International.\n\nSponsor's pledge: the sponsor commits to guiding the new member so they understand the club and Lionism, to encouraging them to attend functions, and to helping them become a committed Lion.\n\nRededication pledge: members renew their commitment to the ideals of the organization and its founders, as expressed in the Code of Ethics and Lions purposes, and promise to keep serving wherever help is needed.", "facts": [], "tags": ["pledge"], "related": ["code-of-ethics", "new-member-first-steps"], "src": []}, {"id": "leadership-training", "cat": "values", "level": "member", "title": "Leadership training institutes", "questions": ["what leadership training does lions offer", "what is fdi", "what is rlli", "what is alli", "what is lcip", "lions leadership institute", "faculty development institute"], "answer": "Lions Clubs International offers four main leadership programs.\n\n- Faculty Development Institute (FDI): trains Lions and Leos to teach and facilitate at club, district and multiple district level.\n- Regional Lions Leadership Institute (RLLI): prepares members for leadership roles across the association and can be adapted to local needs.\n- Advanced Lions Leadership Institute (ALLI): builds project management, conflict resolution and teamwork skills for Lions and Leos who have completed a successful term as club president and want to lead at zone, region or district level.\n- Lions Certified Instructor Program (LCIP): trains and certifies Lions with a training or teaching background to serve as faculty at international level, including seminars for incoming district governors.", "facts": [], "tags": ["leadership", "training"], "related": ["lions-mentoring"], "src": []}]};